import type { DncCalculation } from 'app/club-tenant/model/club';
import { UNRANKED_RACE_RANK, type PublishedRace } from 'app/published-results/model/published-race';
import type { Race } from 'app/race-calender/model/race';
import type { SeriesEntry } from 'app/results-input';
import type { RaceCompetitor } from 'app/results-input/model/race-competitor';
import type { ScoringConfiguration } from 'app/scoring/model/scoring-configuration';
import { computeDncPoints } from 'app/scoring/services/dnc-policy';
import { mergeKeyFor, type MergeStrategy } from 'app/scoring/services/merge-key';
import { competitorsForConfigRace } from './eligibility';
import { countableSeriesEntryIds, isCountingCompetitorResultCode } from './counting-policy';

export interface DncContext {
  dncPoints: number;
  countableEntryIds: Set<string>;
}

export const DEFAULT_DNC_POLICY: DncCalculation = {
  basis: 'SeriesEntries',
  offset: 1,
  excludeNeverRaced: false,
};

export function buildDncContext(args: {
  racesToScore: Race[];
  config: ScoringConfiguration;
  seriesEntries: SeriesEntry[];
  allSeriesCompetitors: RaceCompetitor[];
  mergeStrategy: MergeStrategy;
  dncPolicy: DncCalculation;
}): DncContext {
  const { racesToScore, config, seriesEntries, allSeriesCompetitors, mergeStrategy, dncPolicy } = args;

  const competitorsForScoredRaces = racesToScore.flatMap(race =>
    competitorsForConfigRace(race, config, allSeriesCompetitors, seriesEntries),
  );
  const countableEntryIds = countableSeriesEntryIds(competitorsForScoredRaces);
  const dncBasisSeriesEntries = seriesEntries.filter(entry => countableEntryIds.has(entry.id));
  const dncBasisEntriesById = new Map(dncBasisSeriesEntries.map(entry => [entry.id, entry]));

  const dncBasisRaces: PublishedRace[] = racesToScore.map(race => {
    const filteredCompetitors = competitorsForConfigRace(race, config, allSeriesCompetitors, seriesEntries);
    return {
      ...race,
      tagDefinitions: [],
      results: filteredCompetitors
        .filter(comp =>
          countableEntryIds.has(comp.seriesEntryId) &&
          isCountingCompetitorResultCode(comp.resultCode),
        )
        .map(comp => {
          const entry = dncBasisEntriesById.get(comp.seriesEntryId);
          if (!entry) return null;
          return {
            seriesEntryId: comp.seriesEntryId,
            competitorKey: mergeKeyFor(entry, mergeStrategy),
          };
        })
        .filter((result): result is { seriesEntryId: string; competitorKey: string } => result !== null)
        .map(result => ({
          seriesEntryId: result.seriesEntryId,
          competitorKey: result.competitorKey,
          rank: UNRANKED_RACE_RANK,
          boatClass: '',
          sailNumber: 0,
          helm: '',
          crew: '',
          club: '',
          personalHandicapBand: undefined,
          handicap: 0,
          laps: 0,
          startTime: race.scheduledStart,
          finishTime: race.scheduledStart,
          elapsedTime: 0,
          correctedTime: 0,
          points: 0,
          resultCode: 'DNC' as const,
          tags: [],
        })),
    };
  });

  const dncPoints = computeDncPoints(dncPolicy, dncBasisRaces, dncBasisSeriesEntries, mergeStrategy);
  return { dncPoints, countableEntryIds };
}

import { Injectable, inject } from '@angular/core';
import { ClubStore } from 'app/club-tenant';
import { resolveHandicapsForSeries } from 'app/entry/services/entry-helpers';
import { RaceCalendarStore } from 'app/race-calender';
import { Handicap, getHandicapValue } from 'app/scoring/model/handicap';
import { PersonalHandicapBand } from 'app/scoring/model/personal-handicap';
import { ScoreSmarterError } from 'app/shared/utils/scoresmarter-error';
import { RaceCompetitor } from '../model/race-competitor';
import { SeriesEntry } from '../model/series-entry';
import {
  RaceCompetitorMutator,
  SeriesEntryIdentityConflictError,
} from './race-competitor-mutator';
import { RaceCompetitorStore } from './race-competitor-store';
import {
  PerHullIdentity,
  describeIdentity,
  detectInRaceConflict,
  findCollidingEntry,
} from './series-entry-identity';
import { SeriesEntryStore } from './series-entry-store';

/**
 * Per-race overrides are now intentionally minimal. Only `crew` may differ
 * between races for the same hull (handled via `RaceCompetitor.crewOverride`).
 * Every other piece of identity / boat / handicap data lives on the
 * `SeriesEntry` and is therefore inherently series-wide.
 */
export type CrewEditScope = 'raceOnly' | 'wholeSeries';

export type EditOperation =
  | { type: 'setHelm'; value: string }
  | { type: 'setCrew'; value: string; scope: CrewEditScope }
  | { type: 'setBoatClass'; value: string }
  | { type: 'setSailNumber'; value: number }
  | { type: 'setHandicap'; scheme: Handicap['scheme']; value: number }
  | { type: 'setPersonalHandicapBand'; band: PersonalHandicapBand | undefined }
  | { type: 'deleteCompetitor' };

export interface EditRaceCompetitorCommand {
  competitorId: string;
  operation: EditOperation;
}

/**
 * Single-shot edit of every correctable `SeriesEntry` field plus crew.
 * Handicaps are not part of this payload: they are re-resolved from the new
 * class / personal band via `resolveHandicapsForSeries` when those change.
 *
 * `crewScope`: `raceOnly` updates `RaceCompetitor.crewOverride` for this
 * race; `wholeSeries` updates `SeriesEntry.crew` (the post-entry correction
 * form always sends `raceOnly`).
 *
 * Intended for the post-entry correction dialog; the per-operation
 * `EditRaceCompetitorCommand` + `apply()` path remains for other callers.
 */
export interface SeriesEntryEditCommand {
  competitorId: string;
  helm: string;
  crew: string;
  crewScope: CrewEditScope;
  boatClass: string;
  sailNumber: number;
  personalHandicapBand?: PersonalHandicapBand;
  /**
   * User-authored tags for the entry. Omitted means "leave tags unchanged"
   * so legacy callers don't reset them on save.
   */
  tags?: string[];
}

/**
 * Applies edit commands originating from the per-race UI. Logic intentionally
 * isolates per-race scope (only the crew field) from per-hull scope (everything
 * else); see `EditOperation` for the strict allowed shapes.
 */
@Injectable({ providedIn: 'root' })
export class RaceCompetitorEditService {
  private readonly competitors = inject(RaceCompetitorStore);
  private readonly seriesEntries = inject(SeriesEntryStore);
  private readonly raceCalendar = inject(RaceCalendarStore);
  private readonly clubStore = inject(ClubStore);
  private readonly mutator = inject(RaceCompetitorMutator);

  async apply(command: EditRaceCompetitorCommand): Promise<void> {
    const target = this.competitors.selectedCompetitors().find(c => c.id === command.competitorId);
    if (!target) {
      throw new Error(`Competitor not found: ${command.competitorId}`);
    }
    const entry = this.seriesEntries.selectedEntries().find(e => e.id === target.seriesEntryId);
    if (!entry) {
      throw new Error(`SeriesEntry ${target.seriesEntryId} not found for competitor ${target.id}`);
    }

    switch (command.operation.type) {
      case 'deleteCompetitor':
        await this.deleteCompetitor(target);
        return;
      case 'setCrew':
        await this.applyCrew(target, entry, command.operation);
        return;
      case 'setHelm':
      case 'setBoatClass':
      case 'setSailNumber':
      case 'setHandicap':
      case 'setPersonalHandicapBand':
        await this.applyEntryChange(entry, command.operation);
        return;
    }
  }

  private async applyCrew(
    target: RaceCompetitor,
    entry: SeriesEntry,
    op: Extract<EditOperation, { type: 'setCrew' }>,
  ): Promise<void> {
    const trimmed = op.value.trim();
    if (op.scope === 'raceOnly') {
      // crewOverride === undefined means "use entry crew"; we keep the empty
      // string as an explicit override that clears the entry crew for this race.
      const next = trimmed === (entry.crew ?? '') ? undefined : trimmed;
      if ((target.crewOverride ?? null) === (next ?? null)) return;
      await this.competitors.updateResult(target.id, { crewOverride: next });
      return;
    }

    if ((entry.crew ?? '') !== trimmed) {
      await this.seriesEntries.updateEntry(entry.id, { crew: trimmed });
    }
    // Wholeseries: drop any per-race overrides for this entry that now match
    // the new entry crew. We deliberately do NOT touch overrides that still
    // diverge from the new entry crew.
    const allForEntry = this.competitors.selectedCompetitors().filter(c => c.seriesEntryId === entry.id);
    for (const comp of allForEntry) {
      if (comp.crewOverride !== undefined && comp.crewOverride === trimmed) {
        await this.competitors.updateResult(comp.id, { crewOverride: undefined });
      }
    }
  }

  private async applyEntryChange(
    entry: SeriesEntry,
    op: Exclude<EditOperation, { type: 'setCrew' | 'deleteCompetitor' }>,
  ): Promise<void> {
    // Per-hull identity uniqueness is enforced authoritatively by the
    // mutator (it queries series-entries and throws
    // SeriesEntryIdentityConflictError on collision). We translate that to
    // the friendly rename message expected by callers.
    const update: Partial<SeriesEntry> = {};
    switch (op.type) {
      case 'setHelm':
        if (entry.helm === op.value) return;
        update.helm = op.value;
        break;
      case 'setBoatClass':
        if (entry.boatClass === op.value) return;
        update.boatClass = op.value;
        break;
      case 'setSailNumber':
        if (entry.sailNumber === op.value) return;
        update.sailNumber = op.value;
        break;
      case 'setHandicap': {
        const current = getHandicapValue(entry.handicaps, op.scheme);
        if (current === op.value) return;
        const without = (entry.handicaps ?? []).filter(h => h.scheme !== op.scheme);
        update.handicaps = [...without, { scheme: op.scheme, value: op.value }];
        break;
      }
      case 'setPersonalHandicapBand':
        // UI uses `undefined` for unknown; persisted clear is explicit `null` (merge → deleteField).
        if ((entry.personalHandicapBand ?? null) === (op.band ?? null)) return;
        (update as { personalHandicapBand?: PersonalHandicapBand | null }).personalHandicapBand =
          op.band === undefined ? null : op.band;
        break;
    }
    if (Object.keys(update).length === 0) return;

    const next: SeriesEntry = { ...entry, ...update } as SeriesEntry;
    try {
      await this.mutator.updateSeriesEntryFromEdit(entry, next);
    } catch (err) {
      if (err instanceof SeriesEntryIdentityConflictError) {
        throw new ScoreSmarterError(
          `Cannot rename: another series entry already exists for ` +
          `${describeIdentity(err.identity)} (id ${err.collidingEntryId}). ` +
          `Delete or merge that entry before renaming.`,
        );
      }
      throw err;
    }
  }

  private async deleteCompetitor(target: RaceCompetitor): Promise<void> {
    await this.mutator.deleteRaceCompetitor(target);
  }

  /**
   * Single-shot multi-field edit from the post-entry correction dialog.
   *
   * Steps, in order, so that we never half-apply a change:
   * 1. Resolve competitor + entry + series.
   * 2. Build the proposed identity tuple and run duplicate + in-race
   *    conflict checks against the *final* (helm, class, sail).
   * 3. Persist crew using its scope rule (race override vs entry).
   * 4. Recompute handicaps/tags for the new class / band, then write every
   *    changed entry field in one `updateEntry` call.
   * 5. Mark affected races dirty so the existing guards republish on leave.
   */
  async applyEdit(command: SeriesEntryEditCommand): Promise<void> {
    const target = this.competitors.selectedCompetitors().find(c => c.id === command.competitorId);
    if (!target) {
      throw new Error(`Competitor not found: ${command.competitorId}`);
    }
    const entry = this.seriesEntries.selectedEntries().find(e => e.id === target.seriesEntryId);
    if (!entry) {
      throw new Error(`SeriesEntry ${target.seriesEntryId} not found for competitor ${target.id}`);
    }
    const series = this.raceCalendar.allSeries().find(s => s.id === entry.seriesId);
    if (!series) {
      throw new Error(`Series ${entry.seriesId} not found for entry ${entry.id}`);
    }

    const helm = command.helm.trim();
    const crew = command.crew.trim();
    const boatClass = command.boatClass.trim();
    const sailNumber = command.sailNumber;

    const proposed: PerHullIdentity = { helm, boatClass, sailNumber };

    // Same series: another SeriesEntry with this (helm, class, sail) tuple.
    // If it exists, we either error (already represented in this race), run
    // merged-hull/helm checks, then re-point this race row at that entry
    // (same model as EntryService.findOrCreateSeriesEntry on reuse), or — if
    // there is no collision — rename the current entry in place.
    const sameSeriesEntries = this.seriesEntries
      .selectedEntries()
      .filter(e => e.seriesId === entry.seriesId);
    const collision = findCollidingEntry(sameSeriesEntries, proposed, entry.id);
    if (collision) {
      const alreadyInThisRace = this.competitors
        .selectedCompetitors()
        .some(
          c =>
            c.raceId === target.raceId &&
            c.id !== target.id &&
            c.seriesEntryId === collision.id,
        );
      if (alreadyInThisRace) {
        throw new ScoreSmarterError(
          `${describeIdentity(proposed)} is already entered in this race.`,
        );
      }
    }

    // In-race conflict against other competitors in the same race under the
    // series' entry strategy (helm-in-race / hull-in-race). A no-op identity
    // would match the target itself, so we exclude its own competitor row.
    const currentRaceComps = this.competitors
      .selectedCompetitors()
      .filter(c => c.raceId === target.raceId && c.id !== target.id);
    const strategy = series.entryAlgorithm ?? 'classSailNumberHelm';
    for (const comp of currentRaceComps) {
      const otherEntry = this.seriesEntries.selectedEntries().find(e => e.id === comp.seriesEntryId);
      if (!otherEntry) continue;
      const reason = detectInRaceConflict(otherEntry, proposed, strategy);
      if (reason) {
        throw new ScoreSmarterError(
          `Cannot update: ${describeIdentity(proposed)} would conflict with ` +
          `${describeIdentity(otherEntry)} in this race (${reason}).`,
        );
      }
    }

    let workingEntry = entry;
    let competitorForCrew = target;
    if (collision) {
      // Atomic repoint + orphan-cleanup of the now-unused old entry. The
      // mutator validates the target entry belongs to the same series.
      await this.mutator.repointRaceCompetitorToEntry(target, collision.id, {
        cleanupOldEntry: 'ifOrphan',
      });
      workingEntry = collision;
      const refreshed = this.competitors.selectedCompetitors().find(c => c.id === target.id);
      // Live store may not yet reflect the write; fall back to a synthesised
      // row whose `seriesEntryId` matches the new target so crew-scope
      // comparisons against `workingEntry` stay correct.
      competitorForCrew = refreshed ?? new RaceCompetitor({ ...target, seriesEntryId: collision.id });
    }

    // Crew: the only field with per-race scope. We apply it first so a
    // downstream entry-write failure can't leave the race row mutated in a
    // way that contradicts the entry's crew.
    const crewScopeChanged = await this.applyCrewEdit(
      competitorForCrew,
      workingEntry,
      crew,
      command.crewScope,
    );

    // Entry field changes. Handicaps are re-resolved *only* when the boat
    // class or personal band actually changed; a bare helm/crew correction
    // must not silently rewrite handicaps and republish every race in the
    // series.
    /** When absent, callers are not intending to edit the saved band — avoid spurious clears. */
    const commandSpecifiesBand = Object.prototype.hasOwnProperty.call(command, 'personalHandicapBand');
    const personalHandicapBand = command.personalHandicapBand;
    const classChanged = workingEntry.boatClass !== boatClass;
    const bandChanged =
      commandSpecifiesBand &&
      (workingEntry.personalHandicapBand ?? undefined) !== (personalHandicapBand ?? undefined);

    const entryUpdate: Partial<SeriesEntry> = {};
    if (workingEntry.helm !== helm) entryUpdate.helm = helm;
    if (classChanged) entryUpdate.boatClass = boatClass;
    if (workingEntry.sailNumber !== sailNumber) entryUpdate.sailNumber = sailNumber;
    if (bandChanged) {
      (entryUpdate as { personalHandicapBand?: PersonalHandicapBand | null }).personalHandicapBand =
        personalHandicapBand === undefined ? null : personalHandicapBand;
    }

    if (classChanged || bandChanged) {
      // When the hull's class changes, do not pass the old `workingEntry.handicaps`
      // into the resolver: valid PY (etc.) on the entry are treated as user
      // overrides and would otherwise stick to the previous class's numbers.
      // A class change means "take handicaps from the new club class (+ band
      // rules)" — same as the entry form preview. Band-only edits keep the
      // existing handicap array so PY-based Personal math stays stable.
      const recomputed = resolveHandicapsForSeries(
        series,
        {
          boatClassName: boatClass,
          handicaps: classChanged ? undefined : workingEntry.handicaps,
          personalHandicapBand,
          personalHandicapUnknown: !personalHandicapBand,
        },
        this.clubStore.club().classes,
      );
      if (!handicapsEqual(workingEntry.handicaps, recomputed)) {
        entryUpdate.handicaps = recomputed;
      }
    }

    // User-tag edits flow through `command.tags`. When omitted we keep
    // the existing tags; when supplied we replace them wholesale.
    if (command.tags !== undefined) {
      const nextTags = [...command.tags];
      if (!tagsEqual(workingEntry.tags, nextTags)) {
        entryUpdate.tags = nextTags;
      }
    }

    const entryChanged = Object.keys(entryUpdate).length > 0;
    if (entryChanged) {
      const next: SeriesEntry = { ...workingEntry, ...entryUpdate } as SeriesEntry;
      try {
        await this.mutator.updateSeriesEntryFromEdit(workingEntry, next);
      } catch (err) {
        if (err instanceof SeriesEntryIdentityConflictError) {
          throw new ScoreSmarterError(
            `Cannot update: another series entry already exists for ` +
            `${describeIdentity(err.identity)} (id ${err.collidingEntryId}).`,
          );
        }
        throw err;
      }
    }

    // Dirty marking: every race that references this entry is now stale for
    // series-scope changes. For a pure race-only crew edit we only touch the
    // current race. The set is always a superset of the current race when
    // any entry field changed.
    const raceIdsToMark = new Set<string>();
    if (collision) {
      raceIdsToMark.add(target.raceId);
    }
    if (crewScopeChanged === 'race') {
      raceIdsToMark.add(target.raceId);
    }
    if (entryChanged || crewScopeChanged === 'series') {
      for (const comp of this.competitors.selectedCompetitors()) {
        if (comp.seriesEntryId === workingEntry.id) raceIdsToMark.add(comp.raceId);
      }
    }
    for (const raceId of raceIdsToMark) {
      await this.raceCalendar.updateRace(raceId, { dirty: true });
    }
  }

  /**
   * Returns `'race'` when only the current `RaceCompetitor.crewOverride` was
   * touched, `'series'` when the entry crew was written, or `null` when the
   * value was already in sync with the selected scope.
   */
  private async applyCrewEdit(
    target: RaceCompetitor,
    entry: SeriesEntry,
    crew: string,
    scope: CrewEditScope,
  ): Promise<'race' | 'series' | null> {
    if (scope === 'raceOnly') {
      // `undefined` means "use the entry crew"; a deliberate empty string
      // override clears the entry crew for this race only.
      const next = crew === (entry.crew ?? '') ? undefined : crew;
      if ((target.crewOverride ?? null) === (next ?? null)) return null;
      await this.competitors.updateResult(target.id, { crewOverride: next });
      return 'race';
    }

    let changed = false;
    if ((entry.crew ?? '') !== crew) {
      await this.seriesEntries.updateEntry(entry.id, { crew });
      changed = true;
    }
    // Drop per-race overrides that now equal the new entry crew; we keep
    // overrides that still intentionally diverge.
    const allForEntry = this.competitors.selectedCompetitors().filter(c => c.seriesEntryId === entry.id);
    for (const comp of allForEntry) {
      if (comp.crewOverride !== undefined && comp.crewOverride === crew) {
        await this.competitors.updateResult(comp.id, { crewOverride: undefined });
        changed = true;
      }
    }
    return changed ? 'series' : null;
  }
}

function handicapsEqual(a: Handicap[] | undefined, b: Handicap[] | undefined): boolean {
  const ax = [...(a ?? [])].sort((x, y) => x.scheme.localeCompare(y.scheme));
  const bx = [...(b ?? [])].sort((x, y) => x.scheme.localeCompare(y.scheme));
  if (ax.length !== bx.length) return false;
  for (let i = 0; i < ax.length; i++) {
    if (ax[i].scheme !== bx[i].scheme || ax[i].value !== bx[i].value) return false;
  }
  return true;
}

function tagsEqual(a: string[] | undefined, b: string[] | undefined): boolean {
  const ax = [...(a ?? [])].sort();
  const bx = [...(b ?? [])].sort();
  if (ax.length !== bx.length) return false;
  return ax.every((t, i) => t === bx[i]);
}

import { ChangeDetectionStrategy, Component, computed, inject, signal } from '@angular/core';
import { MatButtonModule } from '@angular/material/button';
import { MAT_DIALOG_DATA, MatDialogModule, MatDialogRef } from '@angular/material/dialog';
import { RaceCalendarStore } from 'app/race-calender';
import { ResolvedRaceCompetitor } from 'app/results-input/model/resolved-race-competitor';
import { DeleteButton } from "app/shared/components/delete-button";
import { DialogsService } from 'app/shared/dialogs/dialogs.service';
import { ScoreSmarterError } from 'app/shared/utils/scoresmarter-error';
import {
  RaceCompetitorEditService,
  SeriesEntryEditCommand,
} from '../../services/race-competitor-edit.service';
import { SeriesEntryEditForm } from '../series-entry-edit-form/series-entry-edit-form';

export interface EditRaceCompetitorDialogData {
  /** The race row being edited - identity comes from its SeriesEntry. */
  competitor: ResolvedRaceCompetitor;
}

/**
 * Result of the correction dialog. Callers rarely need to inspect this; the
 * dialog itself has already applied the change by the time it closes with
 * `saved` or `deleted`. `undefined` is returned when the user cancels or
 * dismisses without committing.
 */
export type EditRaceCompetitorDialogResult =
  | { kind: 'saved'; }
  | { kind: 'deleted'; }
  | undefined;

/**
 * Correction dialog for a single race competitor (post-entry typo fixes).
 *
 * Hosts `SeriesEntryEditForm` for the main edit flow and exposes a separate
 * Delete action with a confirm step. The dialog owns the
 * `RaceCompetitorEditService.applyEdit` call so a collision error can be
 * surfaced in-place without closing the form.
 */
@Component({
  selector: 'app-edit-race-competitor-dialog',
  imports: [MatDialogModule, MatButtonModule, SeriesEntryEditForm, DeleteButton],
  template: `
    <h3 mat-dialog-title>Edit competitor</h3>
    <mat-dialog-content>
      @if (series(); as s) {
        <app-series-entry-edit-form
          [competitor]="data.competitor"
          [series]="s"
          (submitCommand)="onSubmit($event)"
          (cancelled)="dialogRef.close()"
        />
      } @else {
        <p class="warn">Series not loaded - cannot edit this row.</p>
      }

      @if (errorMessage(); as msg) {
        <p class="error" role="alert">{{ msg }}</p>
      }
    </mat-dialog-content>
    <mat-dialog-actions align="start">
      <app-delete-button [busy]="saving()" (delete)="onDelete()">
        Delete Race Entry
      </app-delete-button>
    </mat-dialog-actions>
  `,
  styles: [`
    :host { display: block; max-width: 100%; }
    .error { color: var(--mat-sys-error); margin: 4px 0 0; font-size: 12px; }
    .warn { color: var(--mat-sys-error); }
    mat-dialog-actions {
      border-top: 1px solid var(--mat-sys-outline-variant);
      margin-top: 8px;
      padding-top: 8px;
    }
  `],
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class EditRaceCompetitorDialog {
  readonly dialogRef = inject(MatDialogRef<EditRaceCompetitorDialog, EditRaceCompetitorDialogResult>);
  protected readonly data = inject<EditRaceCompetitorDialogData>(MAT_DIALOG_DATA);
  private readonly editService = inject(RaceCompetitorEditService);
  private readonly raceCalendar = inject(RaceCalendarStore);
  private readonly dialogs = inject(DialogsService);

  protected readonly saving = signal(false);
  protected readonly errorMessage = signal<string | undefined>(undefined);

  protected readonly series = computed(() =>
    this.raceCalendar.allSeries().find(s => s.id === this.data.competitor.seriesId),
  );

  async onSubmit(command: SeriesEntryEditCommand): Promise<void> {
    this.errorMessage.set(undefined);
    this.saving.set(true);
    try {
      await this.editService.applyEdit(command);
      this.dialogRef.close({ kind: 'saved' });
    } catch (err) {
      // Keep the dialog open on a collision so the user can adjust the
      // field that caused it; other errors still surface the same way.
      const msg =
        err instanceof ScoreSmarterError
          ? err.message
          : err instanceof Error
            ? err.message
            : 'Failed to save changes.';
      this.errorMessage.set(msg);
    } finally {
      this.saving.set(false);
    }
  }

  async onDelete(): Promise<void> {
    const ok = await this.dialogs.confirm(
      'Delete competitor',
      `Remove ${this.data.competitor.helm} from this race?`,
    );
    if (!ok) return;
    this.saving.set(true);
    try {
      await this.editService.apply({
        competitorId: this.data.competitor.id,
        operation: { type: 'deleteCompetitor' },
      });
      this.dialogRef.close({ kind: 'deleted' });
    } catch (err) {
      this.errorMessage.set(err instanceof Error ? err.message : 'Delete failed.');
    } finally {
      this.saving.set(false);
    }
  }
}

import { Injectable, inject } from '@angular/core';
import { RaceCalendarStore } from 'app/race-calender';
import {
  RaceCompetitorMutator,
  SeriesEntryIdentityConflictError,
} from 'app/results-input/services/race-competitor-mutator';
import { SeriesEntryStore } from 'app/results-input/services/series-entry-store';
import { ScoreSmarterError } from 'app/shared/utils/scoresmarter-error';
import { ClubStore } from '../../club-tenant';
import { Race } from '../../race-calender/model/race';
import { RaceCompetitor } from '../../results-input/model/race-competitor';
import { SeriesEntry } from '../../results-input/model/series-entry';
import { RaceCompetitorStore } from '../../results-input/services/race-competitor-store';
import { Handicap } from 'app/scoring/model/handicap';
import { PersonalHandicapBand } from 'app/scoring/model/personal-handicap';
import { SeriesEntryPartialUpdate } from 'app/results-input/services/series-entry-store';
import { resolveHandicapsForSeries } from './entry-helpers';
import {
  PerHullIdentity,
  describeIdentity,
  detectInRaceConflict,
  EntryConflictReason,
  findAllMatchingEntries,
} from 'app/results-input/services/series-entry-identity';

export interface EntryDetails {
  races: Race[];
  helm: string;
  crew?: string;
  boatClass: string;
  sailNumber: number;
  handicaps?: Handicap[];
  personalHandicapBand?: PersonalHandicapBand;
  /**
   * Tag ids to seed on a newly-created SeriesEntry. Typically `Boat.tags`
   * forwarded by the entry UI. Existing entries keep their tags - the RO
   * may have overridden them; this field is ignored on the reuse path.
   * Optional: omitted/undefined is treated as no boat tags (`[]`).
   */
  tags?: string[];
}

/**
 * A pre-existing race entry that prevents the proposed sign-on. Surfaced to
 * the UI so the user can choose to overwrite (boat-swap) or cancel; never
 * reported when the proposed entry can simply be added.
 */
export interface EntryConflict {
  race: Race;
  reason: EntryConflictReason;
  existingCompetitor: RaceCompetitor;
  existingEntry: SeriesEntry;
}

/**
 * Per-hull SeriesEntry creation.
 *
 * Each unique (boatClass, sailNumber, helm) tuple in a series corresponds to
 * exactly one SeriesEntry. The series-level `entryAlgorithm` only controls
 * how those entries are *merged at scoring time* into competitor groups (see
 * `mergeKeyFor`); it no longer affects how entries are created or how
 * duplicate sign-on is detected. This guarantees per-hull data (handicap,
 * boat class) is never overwritten when one helm sails multiple boats in
 * the same series.
 */
@Injectable({
  providedIn: 'root'
})
export class EntryService {
  private clubStore = inject(ClubStore);
  private raceResultsStore = inject(RaceCompetitorStore);
  private seriesEntryStore = inject(SeriesEntryStore);
  private raceCalanderStore = inject(RaceCalendarStore);
  private mutator = inject(RaceCompetitorMutator);

  /** Enter a race
   * throws a ScoreSmarterError exception if any conflict is detected.
   *
   * Callers that want to surface conflicts to the user (boat-swap UX) should
   * call `findEntryConflicts` first and, if appropriate, `swapAndEnter`. This
   * method is a strict guard for any caller that doesn't.
   */
  async enterRaces(details: EntryDetails): Promise<void> {

    const conflicts = this.findEntryConflicts(details);
    if (conflicts.length > 0) {
      throw new ScoreSmarterError(
        `Entry conflict for ${describeIdentity({
          boatClass: details.boatClass,
          sailNumber: details.sailNumber,
          helm: details.helm,
        })}`,
      );
    }

    for (const race of details.races) {
      const series = this.raceCalanderStore.allSeries().find(s => s.id === race.seriesId);
      if (!series) {
        const msg = 'EntryService: Series not found for race: ' + race.toString();
        console.error(msg);
        throw new ScoreSmarterError(msg);
      }

      const handicapsForEntry = resolveHandicapsForSeries(series, {
        boatClassName: details.boatClass,
        handicaps: details.handicaps,
        personalHandicapBand: details.personalHandicapBand,
        personalHandicapUnknown: !details.personalHandicapBand,
      }, this.clubStore.club().classes);

      const seriesEntryId =
        await this.findOrCreateSeriesEntry(race, details, handicapsForEntry);

      const competitor: Partial<RaceCompetitor> = {
        raceId: race.id,
        seriesId: race.seriesId,
        seriesEntryId,
        resultCode: 'NOT FINISHED',
      };

      await this.raceResultsStore.addResult(competitor);
    }
  }

  /**
   * Find every existing race entry that prevents the proposed sign-on across
   * the selected races. Each conflict is reported with its reason (exact-hull
   * duplicate, helm-already-in-race for merged-helm series, hull-already-in-
   * race for merged-hull series) so the caller can present a swap dialog.
   *
   * Joins each per-race competitor row to its SeriesEntry because identity
   * fields (helm/boatClass/sailNumber) live on the entry, not on the race
   * competitor.
   */
  findEntryConflicts(details: EntryDetails): EntryConflict[] {
    const incoming: PerHullIdentity = {
      boatClass: details.boatClass,
      sailNumber: details.sailNumber,
      helm: details.helm,
    };

    const entriesById = new Map(
      this.seriesEntryStore.selectedEntries().map(e => [e.id, e] as const),
    );
    const allComps = this.raceResultsStore.selectedCompetitors();
    const conflicts: EntryConflict[] = [];

    for (const race of details.races) {
      const series = this.raceCalanderStore.allSeries().find(s => s.id === race.seriesId);
      // Default to the strictest strategy if the series can't be located so
      // we never silently downgrade conflict detection.
      const strategy = series?.entryAlgorithm ?? 'classSailNumberHelm';

      for (const comp of allComps) {
        if (comp.raceId !== race.id) continue;
        const entry = entriesById.get(comp.seriesEntryId);
        if (!entry) continue;
        const reason = detectInRaceConflict(entry, incoming, strategy);
        if (reason) {
          conflicts.push({ race, reason, existingCompetitor: comp, existingEntry: entry });
        }
      }
    }

    return conflicts;
  }

  /**
   * Boat-swap path: delete every conflicting race competitor, then proceed
   * with the requested entry. The caller is expected to have already
   * obtained the user's consent via the conflict dialog.
   *
   * The deletion is per-race: an existing entry that is also used in OTHER
   * races stays put and only loses its row in the conflicting race(s).
   * Orphaned `SeriesEntry` documents are removed atomically by the mutator's
   * batched `deleteRaceCompetitor` (per-conflict authoritative orphan check).
   */
  async swapAndEnter(details: EntryDetails, conflicts: EntryConflict[]): Promise<void> {
    for (const conflict of conflicts) {
      await this.mutator.deleteRaceCompetitor(conflict.existingCompetitor);
    }

    // Re-evaluate after the deletions so we don't sign in twice if the same
    // race appeared in `conflicts` AND another later code path tries to add
    // it again. After the swap there must be no remaining conflicts; if there
    // are, the caller's view of the world was stale and we abort loudly.
    const remaining = this.findEntryConflicts(details);
    if (remaining.length > 0) {
      throw new ScoreSmarterError(
        `Boat swap could not clear all conflicts (${remaining.length} remaining). ` +
        `Refresh and try again.`,
      );
    }

    await this.enterRaces(details);
  }

  /**
   * Find an existing per-hull SeriesEntry (matched by boatClass + sailNumber +
   * helm) or create one. Updates the entry's handicaps/personalHandicapBand
   * to the latest input so they stay current; identity fields are preserved.
   */
  async findOrCreateSeriesEntry(race: Race, details: EntryDetails, handicaps: Handicap[]): Promise<string> {
    const seriesEntries = this.seriesEntryStore.selectedEntries()
      .filter(e => e.seriesId === race.seriesId);

    const identity: PerHullIdentity = {
      boatClass: details.boatClass,
      sailNumber: details.sailNumber,
      helm: details.helm,
    };
    const matches = findAllMatchingEntries(seriesEntries, identity);

    // Per-hull invariant: at most one SeriesEntry should ever match a given
    // (helm, boatClass, sailNumber). Detecting more than one means a previous
    // write (a rename, a manual Firestore edit, or a pre-refactor merge) has
    // corrupted the dataset. Refuse to write more results against either
    // entry until the duplicate is resolved.
    if (matches.length > 1) {
      throw new ScoreSmarterError(
        `Data integrity error: ${matches.length} SeriesEntries already match ` +
        `${describeIdentity(identity)} in series ${race.seriesId} ` +
        `(ids: ${matches.map(e => e.id).join(', ')}). ` +
        `Resolve the duplicate before continuing.`,
      );
    }

    const existing = matches[0];

    if (existing) {
      // Reuse path: refresh derived fields only. Tags are user-authored and
      // may have been overridden by an RO on the existing entry; do not
      // overwrite them with the incoming boat tags.
      //
      // `personalHandicapBand` is passed as `null` when the caller has no
      // band so the typed converter clears the field via `deleteField()`
      // on the partial write. Passing raw `undefined` would be *omitted*
      // by the converter (leave any stale band intact). The `null`
      // sentinel is part of the converter contract documented in
      // `firestore-helper.ts`.
      const entryUpdate: SeriesEntryPartialUpdate = {
        handicaps,
        personalHandicapBand: details.personalHandicapBand ?? null,
      };
      if (details.crew !== undefined && details.crew !== existing.crew) {
        entryUpdate.crew = details.crew;
      }
      await this.seriesEntryStore.updateEntry(existing.id, entryUpdate);
      return existing.id;
    }

    console.log(`EntryService: Adding series entry ${race.seriesName} index: ${race.index}`);

    try {
      return await this.mutator.createSeriesEntry({
        seriesId: race.seriesId,
        helm: details.helm,
        crew: details.crew,
        boatClass: details.boatClass,
        sailNumber: details.sailNumber,
        handicaps,
        personalHandicapBand: details.personalHandicapBand,
        tags: details.tags ?? [],
      });
    } catch (err) {
      // The mutator runs an authoritative collision check that may surface a
      // duplicate the cached `findAllMatchingEntries` above missed (e.g. a
      // concurrent sign-on, or a stale store snapshot). Translate it to the
      // same `ScoreSmarterError` shape callers already handle.
      if (err instanceof SeriesEntryIdentityConflictError) {
        throw new ScoreSmarterError(
          `Cannot create series entry: another entry already exists for ` +
          `${describeIdentity(identity)} in series ${race.seriesId} ` +
          `(id ${err.collidingEntryId}).`,
        );
      }
      throw err;
    }
  }
}

