const RACE_PATCH_KEYS: (keyof RaceScopedCompetitorPatch)[] = [
  'crewOverride',
  'recordedFinishTime',
  'manualFinishTime',
  'manualLaps',
  'manualPosition',
  'startTime',
  'resultCode',
];

function mergePayloadFromRacePatch(patch: RaceScopedCompetitorPatch): Partial<RaceCompetitor> {
  const out: Partial<RaceCompetitor> = {};
  for (const k of RACE_PATCH_KEYS) {
    if (!(k in patch)) continue;
    const v = patch[k as keyof RaceScopedCompetitorPatch];
    if (v === undefined) continue;
    (out as Record<string, unknown>)[k] = v;
  }
  return out;
}

function handicapListsEqual(a: Handicap[] | undefined, b: Handicap[] | undefined): boolean {
  const ax = [...(a ?? [])].sort((x, y) => x.scheme.localeCompare(y.scheme));
  const bx = [...(b ?? [])].sort((x, y) => x.scheme.localeCompare(y.scheme));
  if (ax.length !== bx.length) return false;
  for (let i = 0; i < ax.length; i++) {
    if (ax[i].scheme !== bx[i].scheme || ax[i].value !== bx[i].value) return false;
  }
  return true;
}

function tagListsEqual(a: string[] | undefined, b: string[] | undefined): boolean {
  const ax = [...(a ?? [])].sort();
  const bx = [...(b ?? [])].sort();
  if (ax.length !== bx.length) return false;
  return ax.every((t, i) => t === bx[i]);
}

/** True when persisted entry fields match (including optional band as null vs absent). */
function seriesEntriesEqual(a: SeriesEntry, b: SeriesEntry): boolean {
  return (
    a.id === b.id &&
    a.seriesId === b.seriesId &&
    a.helm === b.helm &&
    (a.crew ?? '') === (b.crew ?? '') &&
    (a.club ?? '') === (b.club ?? '') &&
    a.boatClass === b.boatClass &&
    a.sailNumber === b.sailNumber &&
    (a.personalHandicapBand ?? null) === (b.personalHandicapBand ?? null) &&
    handicapListsEqual(a.handicaps, b.handicaps) &&
    tagListsEqual(a.tags, b.tags)
  );
}

@Injectable({ providedIn: 'root' })
export class RaceCompetitorMutator {
  private readonly firestore = inject(Firestore);
  private readonly raceCompetitors = inject(RaceCompetitorStore);
  private readonly seriesEntries = inject(SeriesEntryStore);
  private readonly raceCalendar = inject(RaceCalendarStore);

  private async runInBatch(work: (batch: ReturnType<typeof writeBatch>) => void | Promise<void>): Promise<void> {
    const batch = writeBatch(this.firestore);
    await Promise.resolve(work(batch));
    await batch.commit();
  }

  // --- Race-scoped writes ----------------------------------------------------

  /**
   * Single merge write: `setDoc` is enough (no transaction with other docs).
   * Multi-row updates use `writeBatch` in `updateRaceCompetitorsBulk`.
   */
  async updateRaceCompetitor(competitorId: string, patch: RaceScopedCompetitorPatch): Promise<void> {
    const mergePayload = mergePayloadFromRacePatch(patch);
    if (Object.keys(mergePayload).length === 0) return;

    await setDoc(
      this.raceCompetitors.raceResultDocRef(competitorId),
      mergePayload as RaceCompetitor,
      { merge: true },
    );

    const comp = this.raceCompetitors.selectedCompetitors().find(c => c.id === competitorId);
    if (comp) {
      await this.raceCalendar.ensureRaceDirty(comp.raceId);
    }
  }

  /**
   * Per-row race-scoped merges for one race in one atomic batch.
   * Validates each competitor belongs to `raceId`.
   */
  async updateRaceCompetitorsBulk(
    raceId: string,
    rows: { competitorId: string; patch: RaceScopedCompetitorPatch }[],
  ): Promise<void> {
    if (rows.length === 0) return;

    const selected = this.raceCompetitors.selectedCompetitors();
    let wroteAny = false;
    await this.runInBatch(batch => {
      for (const { competitorId, patch } of rows) {
        const comp = selected.find(c => c.id === competitorId);
        if (!comp || comp.raceId !== raceId) {
          throw new ScoreSmarterError(
            `RaceCompetitorMutator: competitor ${competitorId} not in race ${raceId} or not in current selection.`,
          );
        }
        const mergePayload = mergePayloadFromRacePatch(patch);
        if (Object.keys(mergePayload).length === 0) continue;
        wroteAny = true;
        batch.set(this.raceCompetitors.raceResultDocRef(competitorId), mergePayload as RaceCompetitor, {
          merge: true,
        });
      }
    });

    if (wroteAny) {
      await this.raceCalendar.ensureRaceDirty(raceId);
    }
  }

  // --- Series-entry writes (per-hull uniqueness enforced) --------------------

  /**
   * Create a SeriesEntry, refusing if another entry in the same series already
   * has the same per-hull identity.
   */
  async createSeriesEntry(input: CreateSeriesEntryInput): Promise<string> {
    const identity: PerHullIdentity = {
      helm: input.helm,
      boatClass: input.boatClass,
      sailNumber: input.sailNumber,
    };
    await this.assertIdentityFreeInSeries(input.seriesId, identity);

    const entry: Partial<SeriesEntry> = {
      seriesId: input.seriesId,
      helm: input.helm,
      boatClass: input.boatClass,
      sailNumber: input.sailNumber,
      crew: input.crew,
      handicaps: input.handicaps,
      personalHandicapBand: input.personalHandicapBand,
      tags: input.tags,
    };
    return await this.seriesEntries.addEntry(entry);
  }

  /**
   * Writes the full proposed `SeriesEntry` with merge semantics. Identity-changing
   * updates are validated against all current entries in the series.
   */
  async updateSeriesEntryFromEdit(previous: SeriesEntry, next: SeriesEntry): Promise<void> {
    if (previous.id !== next.id) {
      throw new ScoreSmarterError(
        `RaceCompetitorMutator.updateSeriesEntryFromEdit: entry id mismatch ${previous.id} vs ${next.id}.`,
      );
    }
    if (previous.seriesId !== next.seriesId) {
      throw new ScoreSmarterError(
        `RaceCompetitorMutator.updateSeriesEntryFromEdit: cannot change seriesId for entry ${previous.id}.`,
      );
    }
    if (seriesEntriesEqual(previous, next)) return;

    const identityChanged =
      previous.helm !== next.helm ||
      previous.boatClass !== next.boatClass ||
      previous.sailNumber !== next.sailNumber;

    if (identityChanged) {
      const proposed: PerHullIdentity = {
        helm: next.helm,
        boatClass: next.boatClass,
        sailNumber: next.sailNumber,
      };
      const sameSeries = await this.seriesEntries.getSeriesEntries(previous.seriesId);
      const collision = findCollidingEntry(sameSeries, proposed, previous.id);
      if (collision) {
        throw new SeriesEntryIdentityConflictError(collision.id, previous.seriesId, proposed);
      }
    }

    const { id: _omitId, ...payload } = next;

    await this.runInBatch(batch => {
      batch.set(this.seriesEntries.seriesEntryDocRef(previous.id), payload as SeriesEntry, { merge: true });
    });

    const refs = await this.raceCompetitors.getCompetitorsForSeriesEntry(previous.id);
    const raceIds = [...new Set(refs.map(c => c.raceId))];
    for (const rid of raceIds) {
      await this.raceCalendar.ensureRaceDirty(rid);
    }
  }

  // --- Delete / repoint ------------------------------------------------------

  async deleteRaceCompetitor(competitor: RaceCompetitor): Promise<void> {
    const seriesEntryId = competitor.seriesEntryId;

    const others = (await this.raceCompetitors.getCompetitorsForSeriesEntry(seriesEntryId)).filter(
      c => c.id !== competitor.id,
    );

    await this.runInBatch(batch => {
      batch.delete(this.raceCompetitors.raceResultDocRef(competitor.id));
      if (others.length === 0) {
        batch.delete(this.seriesEntries.seriesEntryDocRef(seriesEntryId));
      }
    });

    await this.raceCalendar.ensureRaceDirty(competitor.raceId);
  }

  async repointRaceCompetitorToEntry(
    competitor: RaceCompetitor,
    nextSeriesEntryId: string,
    options?: { cleanupOldEntry?: 'ifOrphan' | 'never' },
  ): Promise<void> {
    const cleanup = options?.cleanupOldEntry ?? 'ifOrphan';
    const oldEntryId = competitor.seriesEntryId;

    const target = await this.seriesEntries.getSeriesEntry(nextSeriesEntryId);
    if (!target) {
      throw new ScoreSmarterError(
        `RaceCompetitorMutator: target series entry ${nextSeriesEntryId} not found.`,
      );
    }
    if (target.seriesId !== competitor.seriesId) {
      throw new ScoreSmarterError(
        `RaceCompetitorMutator: target series entry ${nextSeriesEntryId} is in series ` +
        `${target.seriesId}, expected ${competitor.seriesId}.`,
      );
    }

    const othersOnOld = (await this.raceCompetitors.getCompetitorsForSeriesEntry(oldEntryId)).filter(
      c => c.id !== competitor.id,
    );

    await this.runInBatch(batch => {
      batch.set(
        this.raceCompetitors.raceResultDocRef(competitor.id),
        { seriesEntryId: nextSeriesEntryId } as RaceCompetitor,
        { merge: true },
      );
      if (cleanup === 'ifOrphan' && othersOnOld.length === 0) {
        batch.delete(this.seriesEntries.seriesEntryDocRef(oldEntryId));
      }
    });

    await this.raceCalendar.ensureRaceDirty(competitor.raceId);
  }

  /** Deletes a series-entry doc if no race-results still reference it. */
  async cleanupOrphanedSeriesEntry(seriesEntryId: string, options?: { excludeCompetitorId?: string }): Promise<void> {
    const comps = await this.raceCompetitors.getCompetitorsForSeriesEntry(seriesEntryId);
    const remaining = options?.excludeCompetitorId
      ? comps.filter(c => c.id !== options.excludeCompetitorId)
      : comps;
    if (remaining.length > 0) return;

    await this.runInBatch(batch => {
      batch.delete(this.seriesEntries.seriesEntryDocRef(seriesEntryId));
    });
  }

  // --- Internal helpers ------------------------------------------------------

  private async assertIdentityFreeInSeries(seriesId: string, identity: PerHullIdentity): Promise<void> {
    const entries = await this.seriesEntries.getSeriesEntries(seriesId);
    const collision = findCollidingEntry(entries, identity);
    if (collision) {
      throw new SeriesEntryIdentityConflictError(collision.id, seriesId, identity);
    }
  }
}

/** Identifier helper retained for callers that need to mint ids outside the mutator. */
export function generateSeriesEntryId(boatClass: string, sailNumber: number): string {
  return generateSecureID(10000, `SE-${boatClass}-${sailNumber}`);
}

import { inject, Injectable } from '@angular/core';
import { generateSecureID } from 'app/shared/firebase/firestore-helper';
import { deleteDoc, getDocs, getFirestore, query, setDoc, where, writeBatch, Firestore } from '@angular/fire/firestore';
import { Race } from '../model/race';
import { Series } from '../model/series';
import { FirestoreTenantService } from 'app/club-tenant';

export interface RaceSeriesDetails {
  id: string;
  name: string;
  fleetId: string;
}

@Injectable({
  providedIn: 'root',
})
export class RaceCalendarStoreBase {
  protected readonly firestore = inject(Firestore);
  private readonly tenant = inject(FirestoreTenantService);

  protected ref = (id: string) => this.tenant.docRef<Series>('series', id);
  protected seriesCollection = this.tenant.collectionRef<Series>('series');

  protected raceRef = (id: string) => this.tenant.docRef<Race>('races', id);
  protected racesCollection = this.tenant.collectionRef<Race>('races');

  /** Add a series retruning a document Id */
  async addSeries(series: Partial<Series>): Promise<string> {
    series.archived = false;
    const id = generateSecureID(1000, `S-${series.name}`);
    await setDoc(this.ref(id), series);
    return id;
  }

  async updateSeries(id: string, data: Partial<Series>) {
    const scoringCriticalFields: (keyof Series)[] = [
      'scoringAlgorithm',
      'entryAlgorithm',
      'discards',
      'primaryScoringConfiguration',
      'secondaryScoringConfigurations'
    ];

    const hasScoringChange = scoringCriticalFields.some(field => field in data);
    if (hasScoringChange) {
      data.dirty = true;
    }

    await setDoc(this.ref(id), data, { merge: true });
  }

  async deleteSeries(id: string) {
    // Delete races for the series. 
    const racesSnapshot = await getDocs(query(this.racesCollection, where('seriesId', '==', id)));

    const batch = writeBatch(this.firestore);
    racesSnapshot.forEach(doc => batch.delete(doc.ref));

    // Delete the series in the batch
    batch.delete(this.ref(id));
    await batch.commit();
  }

  async addRace(seriesDetails: RaceSeriesDetails, race: Partial<Race>): Promise<void> {
    race.seriesId = seriesDetails.id;
    race.seriesName = seriesDetails.name;
    race.fleetId = seriesDetails.fleetId;
    race.status = 'Future';
    const id = generateSecureID(10000, `R-${seriesDetails.name}`);
    await setDoc(this.raceRef(id), race);
  }

  async updateRace(raceId: string, data: Partial<Race>): Promise<void> {
    await setDoc(this.raceRef(raceId), data, { merge: true });
  }

  async deleteRace(race: Race): Promise<void> {
    await deleteDoc(this.raceRef(race.id));
  }
}

export function seriesSort(a: Series, b: Series): number {
  if (!a.startDate) {
    return !b.startDate ? 1 : 0;
  }

  if (!b.startDate) {
    return -1;
  }

  const ret = a.startDate.getTime() - b.startDate.getTime();
  if (ret !== 0) {
    return ret;
  } else {
    return a.name.localeCompare(b.name);
  }
}

export function sortRaces(a: Race, b: Race): number {
  const ret = a.scheduledStart.getTime() - b.scheduledStart.getTime();

  if (ret === 0) {
    return a.raceOfDay - b.raceOfDay;
  } else {
    return ret;
  }
}

export interface RaceStart {
  id: string;
  /** Start timestamp on race day (or stopwatch timestamp for elapsed mode). */
  timeOfDay: Date;
  /** Optional fleet target. Undefined means default/no-fleet fallback start. */
  fleetId?: string;
}

import { ChangeDetectionStrategy, Component, inject } from '@angular/core';
import { takeUntilDestroyed } from '@angular/core/rxjs-interop';
import { FormArray, FormControl, FormGroup, ReactiveFormsModule, Validators } from '@angular/forms';
import { MatButtonModule } from '@angular/material/button';
import { MAT_DIALOG_DATA, MatDialogModule, MatDialogRef } from '@angular/material/dialog';
import { MatFormFieldModule } from '@angular/material/form-field';
import { MatInputModule } from '@angular/material/input';
import { MatRadioModule } from '@angular/material/radio';
import { MatSelectModule } from '@angular/material/select';
import { addSeconds, format, startOfDay } from 'date-fns';
import { TimeRecordingMode } from '../../services/manual-results.service';
import { Race } from 'app/race-calender';
import { ClubStore } from 'app/club-tenant';
import type { RaceStart } from 'app/race-calender/model/race-start';
import { getFleetName } from 'app/club-tenant/model/fleet';

export interface RaceStartTimeResult {
  mode: TimeRecordingMode;
  starts: RaceStart[];
}

/**
 * Elapsed (stopwatch) starts are stored as a Date relative to local midnight on
 * the race day. The dialog edits them as a signed offset in minutes so the
 * stopwatch can have been started *before* the class start (negative offset).
 */
export function toStartDateFromElapsedOffset(scheduledStart: Date | string | number, offsetMinutes: number): Date {
  const base = startOfDay(new Date(scheduledStart));
  const seconds = Math.round(offsetMinutes * 60);
  return addSeconds(base, seconds);
}

export function toElapsedOffsetMinutes(scheduledStart: Date | string | number, timeOfDay: Date | string | number): number {
  const base = startOfDay(new Date(scheduledStart));
  const seconds = Math.round((new Date(timeOfDay).getTime() - base.getTime()) / 1000);
  return seconds / 60;
}

function formatElapsedOffsetInput(offsetMinutes: number): string {
  if (Number.isInteger(offsetMinutes)) return String(offsetMinutes);
  return String(Number(offsetMinutes.toFixed(4)));
}

@Component({
  selector: 'app-race-start-time-dialog',
  template: `
    <h2 mat-dialog-title>Set Race Start Time</h2>
    <mat-dialog-content>
      <form [formGroup]="form" class="dialog-form">
        <p>Select the timing method used for this race:</p>
        <mat-radio-group formControlName="mode" class="radio-group">
          <mat-radio-button value="tod">Time of Day (Real Time)</mat-radio-button>
          <mat-radio-button value="elapsed">Stopwatch (Elapsed)</mat-radio-button>
        </mat-radio-group>

        <mat-form-field>
          <mat-label>Number of starts</mat-label>
          <input matInput type="number" min="1" formControlName="startCount">
        </mat-form-field>

        <div formArrayName="starts" class="starts-list">
          @for (group of starts.controls; track $index; let i = $index) {
            <div [formGroupName]="i" class="start-row">
              @if (form.value.mode === 'tod') {
                <mat-form-field>
                  <mat-label>Start Time (HH:mm:ss)</mat-label>
                  <input matInput type="time" step="1" formControlName="time">
                </mat-form-field>
              } @else {
                <mat-form-field>
                  <mat-label>Stopwatch reading (minutes)</mat-label>
                  <input matInput type="number" step="any" formControlName="time">
                  <mat-hint>Reading at start time.</mat-hint>
                </mat-form-field>
              }
              <mat-form-field>
                <mat-label>Fleet (optional)</mat-label>
                <mat-select formControlName="fleetId">
                  <mat-option [value]="''">Default</mat-option>
                  @for (f of fleetOptions; track f.id) {
                    <mat-option [value]="f.id">{{ f.name }}</mat-option>
                  }
                </mat-select>
              </mat-form-field>
            </div>
          }
        </div>

        @if (hasDuplicateFleetSelection()) {
          <div class="error">Each fleet (or No fleet) must only appear once.</div>
        }

      </form>
    </mat-dialog-content>
    <mat-dialog-actions align="end">
      <button matButton mat-dialog-close>Cancel</button>
      <button matButton="filled" [disabled]="form.invalid || hasDuplicateFleetSelection()" (click)="save()">Set Start Time</button>
    </mat-dialog-actions>
  `,
  styles: [`
    .dialog-form { display: flex; flex-direction: column; gap: 16px; min-width: 420px; }
    .radio-group { display: flex; flex-direction: column; gap: 8px; margin-bottom: 8px; }
    .starts-list { display: flex; flex-direction: column; gap: 8px; }
    .start-row { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; }
    .error { color: var(--mat-sys-error); font-size: 12px; margin-top: -8px; }
  `],
  imports: [MatDialogModule, MatButtonModule, MatFormFieldModule, MatInputModule, MatRadioModule, MatSelectModule, ReactiveFormsModule],
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class RaceStartTimeDialog {
  private dialogRef = inject(MatDialogRef<RaceStartTimeDialog>);
  private data = inject<{ race: Race; }>(MAT_DIALOG_DATA);
  private clubStore = inject(ClubStore);

  readonly fleetOptions = this.clubStore.club().fleets
    .filter(f => f.type !== 'GeneralHandicap')
    .map(f => ({ id: f.id, name: getFleetName(f) }));

  readonly form = new FormGroup({
    mode: new FormControl<'tod' | 'elapsed'>(this.data.race.timeInputMode || 'tod', { nonNullable: true }),
    startCount: new FormControl<number>(1, { nonNullable: true, validators: [Validators.required, Validators.min(1)] }),
    starts: new FormArray<FormGroup>([]),
  });

  get starts(): FormArray<FormGroup> {
    return this.form.controls.starts as FormArray<FormGroup>;
  }

  constructor() {
    const { race } = this.data;
    const initialMode = race.timeInputMode || 'tod';
    const existingStarts = race.starts?.length
      ? race.starts.map(s => ({ time: this.formatTimeForMode(initialMode, s.timeOfDay), fleetId: s.fleetId ?? '' }))
      : [{
          time: race.actualStart ? this.formatTimeForMode(initialMode, race.actualStart) : '',
          fleetId: '',
        }];

    this.form.controls.startCount.setValue(existingStarts.length);
    for (const start of existingStarts) {
      this.starts.push(this.createStartRow(start.time, start.fleetId));
    }
    this.form.controls.mode.valueChanges.pipe(takeUntilDestroyed()).subscribe(mode => {
      for (const ctrl of this.starts.controls) {
        const timeCtrl = ctrl.get('time');
        if (!timeCtrl) continue;
        if (mode === 'elapsed') {
          if (!timeCtrl.value) timeCtrl.setValue('0');
          else if (/^\d{2}:\d{2}/.test(String(timeCtrl.value))) timeCtrl.setValue('0');
        } else {
          if (!/^\d{2}:\d{2}/.test(String(timeCtrl.value))) timeCtrl.setValue('');
        }
      }
    });

    this.form.controls.startCount.valueChanges.pipe(takeUntilDestroyed()).subscribe(count => {
      const next = Math.max(1, Number(count || 1));
      while (this.starts.length < next) {
        this.starts.push(this.createStartRow('', ''));
      }
      while (this.starts.length > next) {
        this.starts.removeAt(this.starts.length - 1);
      }
    });
  }

  private createStartRow(time: string, fleetId: string): FormGroup {
    return new FormGroup({
      time: new FormControl<string>(time, Validators.required),
      fleetId: new FormControl<string>(fleetId),
    });
  }

  hasDuplicateFleetSelection(): boolean {
    const values = this.starts.controls.map(ctrl => String(ctrl.get('fleetId')?.value ?? ''));
    const seen = new Set<string>();
    for (const v of values) {
      const key = v || '__NO_FLEET__';
      if (seen.has(key)) return true;
      seen.add(key);
    }
    return false;
  }

  private formatTimeForMode(mode: TimeRecordingMode, timeOfDay: Date | string | number): string {
    if (mode === 'elapsed') {
      return formatElapsedOffsetInput(toElapsedOffsetMinutes(this.data.race.scheduledStart, timeOfDay));
    }
    return format(new Date(timeOfDay), 'HH:mm:ss');
  }

  private toStartDateFromClock(time: string): Date {
    const dateStr = new Date(this.data.race.scheduledStart).toDateString();
    return new Date(`${dateStr} ${time}`);
  }

  private toStartsPayload(mode: TimeRecordingMode): RaceStart[] {
    return this.starts.controls.map((ctrl, i) => {
      const raw = String(ctrl.get('time')?.value ?? '');
      const fleetId = String(ctrl.get('fleetId')?.value ?? '');
      const timeOfDay = mode === 'elapsed'
        ? toStartDateFromElapsedOffset(this.data.race.scheduledStart, Number(raw))
        : this.toStartDateFromClock(raw);
      return {
        id: `start-${i + 1}`,
        timeOfDay,
        ...(fleetId ? { fleetId } : {}),
      };
    });
  }

  save() {
    if (this.form.valid && !this.hasDuplicateFleetSelection()) {
      const { mode } = this.form.getRawValue();
      const starts = this.toStartsPayload(mode);
      this.dialogRef.close({ mode, starts } as RaceStartTimeResult);
    }
  }
}

import { CLUB_TAG_COLORS, type ClubTagDefinition } from 'app/club-tenant/model/club-tag';

/**
 * A tag id resolved against a `ClubTagDefinition[]` snapshot, in a shape
 * that result-table templates can render directly.
 *
 * `unresolved` is `true` when no definition matched - the renderer is
 * expected to use default styling and show the raw `id` instead of a
 * fancy chip.
 */
export interface ResolvedTag {
  id: string;
  /** Display label; falls back to `id` for unresolved tags. */
  label: string;
  /** Hex colour, or `undefined` for default styling. */
  color?: string;
  unresolved: boolean;
}

function labelKey(label: string): string {
  return label.trim().toLowerCase();
}

/**
 * Finds a club tag definition for a raw stored id.
 * Matches exact id, then case-insensitive id, then unique label (legacy fleets
 * sometimes stored display labels such as `Youth` instead of `youth`).
 */
export function findTagDefinition(
  rawId: string,
  definitions: readonly ClubTagDefinition[],
): ClubTagDefinition | undefined {
  if (!rawId) return undefined;

  const exact = definitions.find(d => d.id === rawId);
  if (exact) return exact;

  const lower = rawId.toLowerCase();
  const byId = definitions.find(d => d.id.toLowerCase() === lower);
  if (byId) return byId;

  const key = labelKey(rawId);
  const byLabel = definitions.filter(d => labelKey(d.label) === key);
  return byLabel.length === 1 ? byLabel[0] : undefined;
}

/**
 * Maps stored tag ids to canonical definition ids, deduplicating aliases
 * (e.g. `Youth` + `youth` → `youth`) while preserving first-seen order.
 * Unrecognised ids are kept as-is so callers can still surface them.
 */
export function normalizeTagIds(
  ids: readonly string[],
  definitions: readonly ClubTagDefinition[],
): string[] {
  const out: string[] = [];
  const seen = new Set<string>();

  for (const raw of ids) {
    if (!raw) continue;
    const def = findTagDefinition(raw, definitions);
    const canonical = def?.id ?? raw;
    if (seen.has(canonical)) continue;
    seen.add(canonical);
    out.push(canonical);
  }
  return out;
}

function toResolvedTag(id: string, def: ClubTagDefinition | undefined): ResolvedTag {
  if (!def || !def.label || def.label.trim().length === 0) {
    return {
      id,
      label: id,
      unresolved: true,
    };
  }
  return {
    id: def.id,
    label: def.label,
    color: def.color ? CLUB_TAG_COLORS[def.color] : undefined,
    unresolved: false,
  };
}

/**
 * Resolves `ids` against `definitions`, preserving the input order.
 * Aliases are canonicalized and deduplicated before rendering.
 * Definitions with blank labels are treated as intentionally hidden and
 * surfaced as `unresolved` so callers fall back to default styling.
 *
 * Pure function; no logging, no Angular imports - safe to use from
 * Storybook stories and unit tests as well as live result-table
 * components.
 */
export function resolveTags(
  ids: readonly string[],
  definitions: readonly ClubTagDefinition[],
): ResolvedTag[] {
  const canonicalIds = normalizeTagIds(ids, definitions);
  if (canonicalIds.length === 0) return [];

  const defsById = new Map<string, ClubTagDefinition>();
  for (const def of definitions) defsById.set(def.id, def);

  return canonicalIds.map(id => toResolvedTag(id, defsById.get(id)));
}

