import { inject, Injectable } from '@angular/core';
import { rxResource } from '@angular/core/rxjs-interop';
import { collectionData, deleteDoc, setDoc } from '@angular/fire/firestore';
import { generateSecureID } from 'app/shared/firebase/firestore-helper';
import { normaliseString } from 'app/shared/utils/string-utils';
import { map, Observable } from 'rxjs';
import { Boat } from '../model/boat';
import { FirestoreTenantService } from 'app/club-tenant';

@Injectable({
  providedIn: 'root',
})
export class BoatsStore {
  private readonly tenant = inject(FirestoreTenantService);

  private ref = (id:string) => this.tenant.docRef<Boat>( 'boats', id);
  private boatsCollection = this.tenant.collectionRef<Boat>('boats');

  private readonly boatsResource = rxResource<Boat[], null>({
    stream: (): Observable<Boat[]> =>
      collectionData(this.boatsCollection, { idField: 'id' }).pipe(
        map(boats => boats.map(coerceBoatTags).sort(boatsSort)),
    ),
    defaultValue: [],
  });

  trimStrings(boat: Partial<Boat>): Partial<Boat> {
    const update = { ...boat };
    if (update.helm) {
      update.helm = update.helm.trim();
    }
    if (update.crew) {
      update.crew = update.crew.trim();
    }
    if (update.boatClass) {
      update.boatClass = update.boatClass.trim();
    }
    if (update.name) {
      update.name = update.name.trim();
    }
    // `undefined` cleanup is delegated to the typed `dataObjectConverter`
    // (see `firestore-helper.ts`); partial writes go through
    // `setDoc({ merge: true })` so the converter runs.
    return update;
  }

  /** Collection of all boats */
  readonly boats = this.boatsResource.value.asReadonly();
  readonly isLoading = this.boatsResource.isLoading;
  readonly error = this.boatsResource.error;

  async add(boat: Partial<Boat>): Promise<void> {
    const update = this.trimStrings(boat);
    const id = generateSecureID(1000, `B-${update.boatClass}-${update.sailNumber}`);
    await setDoc(this.ref(id), update);
  }

  /**
   * Partial update of a boat. Uses `setDoc({ merge: true })` rather than
   * `updateDoc` so the typed converter is invoked and `undefined` is omitted
   * (vs the SDK rejecting it with `invalid-argument`). See
   * `firestore-helper.ts` for the partial-write contract.
   */
  async update(id: string, data: Partial<Boat>): Promise<void> {
    const docRef = this.ref(id);
    const update = this.trimStrings(data);
    await setDoc(docRef, update, { merge: true });
  }

  async delete(id: string): Promise<void> {
    const docRef = this.ref(id);
    await deleteDoc(docRef);
  }
}

/** Defaults the mandatory `tags` array for Boats read off the wire. */
function coerceBoatTags(boat: Boat): Boat {
  if (Array.isArray(boat.tags)) return boat;
  return { ...boat, tags: [] };
}

/** Sort boats by sail number then class */
export function boatsSort(a: Boat, b: Boat): number {
  const ca = normaliseString(a.boatClass);
  const cb = normaliseString(b.boatClass);

  if (ca != cb) {
    return ca.localeCompare(cb);
  } else {
    return a.sailNumber < b.sailNumber ? -1 : 1;
  }
}

/** Returns if a boat matches a filter string.
 * Case insensitive 
 */
export function boatFilter(boat: Boat, search: string | null): boolean {

  const filter = normaliseString(search);

  return !filter || filter === '' ||
    normaliseString(boat.name).includes(filter) ||
    normaliseString(boat.helm).includes(filter) ||
    normaliseString(boat.crew).includes(filter) ||
    boat.sailNumber.toString().includes(filter) ||
    normaliseString(boat.boatClass).includes(filter) ||
    (boat.isClub && 'club'.includes(filter));
}

import { inject, Injectable } from '@angular/core';
import { FirebaseApp } from '@angular/fire/app';
import { connectFunctionsEmulator, getFunctions, httpsCallable } from 'firebase/functions';
import { environment } from '../../environments/environment';

/**
 * Upload-only callable for the phone capture lazy route ({@link MobileCapturePage}),
 * avoiding {@link ScannerOrchestrationService} and its Firestore / store graph.
 */
@Injectable({ providedIn: 'root' })
export class CaptureSessionUploadService {
  private readonly app = inject(FirebaseApp);

  async uploadFromCaptureSession(payload: {
    clubId: string;
    sessionId: string;
    token: string;
    imageBase64: string;
    imageMimeType: string;
  }): Promise<{ status: string; storagePath?: string }> {
    const functions = getFunctions(this.app, 'europe-west1');
    if (environment.useEmulators) {
      try { connectFunctionsEmulator(functions, 'localhost', 5001); } catch { /* already configured */ }
    }
    const fn = httpsCallable(functions, 'uploadResultsSheetImageFromSession', { timeout: 120_000 });
    const res = await fn(payload);
    return res.data as { status: string; storagePath?: string };
  }
}

import { Injectable } from '@angular/core';
import { BoatClass } from '../model/boat-class';
import { Handicap, getHandicapValue } from 'app/scoring/model/handicap';
import { HandicapScheme } from 'app/scoring/model/handicap-scheme';
import { getHandicapSchemeMetadata } from 'app/scoring/model/handicap-scheme-metadata';
import { parseCsv, toCsv } from 'app/shared/utils/csv';

const BASE_COLUMNS = ['id', 'name'] as const;

export interface ClassesCsvParseResult {
  classes: Partial<BoatClass>[];
  errors: string[];
}

@Injectable({ providedIn: 'root' })
export class ClassesCsvService {
  buildCsv(classes: BoatClass[], schemes: HandicapScheme[]): string {
    const handicapColumns = schemes.map(s => this.handicapColumn(s));
    const columns = [...BASE_COLUMNS, ...handicapColumns];
    const rows = classes.map(cls => {
      const row: Record<string, string> = {
        id: cls.id,
        name: cls.name,
      };
      for (const scheme of schemes) {
        const value = getHandicapValue(cls.handicaps, scheme);
        row[this.handicapColumn(scheme)] = value == null ? '' : String(value);
      }
      return row;
    });
    return toCsv(columns, rows);
  }

  parseCsv(content: string, schemes: HandicapScheme[]): ClassesCsvParseResult {
    const parsed = parseCsv(content);
    const errors: string[] = [...parsed.errors];
    const headerColumns = parsed.header;
    if (headerColumns.length === 0) {
      return { classes: [], errors: parsed.errors };
    }
    const requiredColumns = [...BASE_COLUMNS];
    const handicapColumns = schemes.map(s => this.handicapColumn(s));
    const expectedColumns = [...requiredColumns, ...handicapColumns];
    const missing = expectedColumns.filter(c => !headerColumns.includes(c));
    if (missing.length > 0) {
      return { classes: [], errors: [`Missing required columns: ${missing.join(', ')}`] };
    }

    const classes: Partial<BoatClass>[] = [];
    for (let i = 0; i < parsed.rows.length; i++) {
      const record = parsed.rows[i];
      const rowResult = this.parseClassRecord(record, schemes, i + 2);
      if (rowResult.error) {
        errors.push(rowResult.error);
      } else if (rowResult.cls) {
        classes.push(rowResult.cls);
      }
    }
    return { classes, errors };
  }

  private parseClassRecord(
    record: Record<string, string>,
    schemes: HandicapScheme[],
    lineNumber: number
  ): { cls?: Partial<BoatClass>; error?: string } {
    const rowErrors: string[] = [];
    const name = (record['name'] ?? '').trim();
    const id = (record['id'] ?? '').trim();

    if (!name) rowErrors.push('name is required');

    const handicaps: Handicap[] = [];
    for (const scheme of schemes) {
      const raw = (record[this.handicapColumn(scheme)] ?? '').trim();
      if (!raw) continue;
      const value = Number(raw);
      const meta = getHandicapSchemeMetadata(scheme);
      if (!Number.isFinite(value) || value <= 0) {
        rowErrors.push(`${this.handicapColumn(scheme)} must be a positive number if provided`);
        continue;
      }
      if (value < meta.min || value > meta.max) {
        rowErrors.push(
          `${this.handicapColumn(scheme)} must be between ${meta.min} and ${meta.max}`
        );
        continue;
      }
      handicaps.push({ scheme, value });
    }

    if (rowErrors.length > 0) {
      return {
        error: `Line ${lineNumber}: ${rowErrors.join('; ')}`,
      };
    }

    const cls: Partial<BoatClass> = {
      name,
      handicaps,
    };
    if (id) {
      cls.id = id;
    }
    return { cls };
  }

  private handicapColumn(scheme: HandicapScheme): string {
    return `handicap${scheme.replace(/[^a-zA-Z0-9]/g, '')}`;
  }
}

