import { computed, inject, Injectable, signal } from '@angular/core';
import type { Race } from 'app/race-calender';
import { RaceCalendarStore } from '../../race-calender/services/full-race-calander';

/** Manages a list of 'currect races'
 * All information for currect races is held in memory
 */
@Injectable({
  providedIn: 'root',
})
export class CurrentRaces {
  private readonly raceStore = inject(RaceCalendarStore);

  /** Races opened explicitly (e.g. historical race from results viewer), not part of "today" auto-selection. */
  private readonly manuallyAddedRaceIds = signal<Set<string>>(new Set<string>());

  /** Fast lookups for races currently present in calendar cache (`allRaces` ids are unique). */
  private readonly allRacesById = computed(
    () => new Map(this.raceStore.allRaces().map(race => [race.id, race] as const)),
  );

  /** Today's race ids from calendar (set for uniqueness + quick union). */
  private readonly todaysRaceIds = computed(() => {
    const ids = new Set<string>();
    for (const race of this.allRacesById().values()) {
      if (isScheduledToday(race)) ids.add(race.id);
    }
    return ids;
  });

  /** Stable ordered list of today's races (time/index), no manual extras. */
  readonly todaysRaces = computed(() => {
    return [...this.allRacesById().values()]
      .filter(isScheduledToday)
      .sort(sortRacesByTimeThenIndex);
  });

  /** Today's races (from calendar) plus any manual extras still present in `allRaces`. */
  readonly selectedRaceIds = computed(() => {
    const racesById = this.allRacesById();
    const todayIds = this.todaysRaceIds();
    const selected = new Set<string>(todayIds);
    for (const id of this.manuallyAddedRaceIds()) {
      if (!racesById.has(id)) continue; // ignore stale ids
      selected.add(id);
    }
    // Preserve deterministic order: today's races first, then manual extras by race time/index.
    const orderedToday = this.todaysRaces().map(race => race.id);
    const manualExtras = [...selected]
      .filter(id => !todayIds.has(id))
      .map(id => racesById.get(id))
      .filter((race): race is Race => race != null)
      .sort(sortRacesByTimeThenIndex)
      .map(race => race.id);

    return [...orderedToday, ...manualExtras];
  });

  readonly selectedRaces = computed(() => {
    const racesById = this.allRacesById();
    return this.selectedRaceIds()
      .map(id => racesById.get(id))
      .filter((race): race is Race => race != null);
  });

  readonly selectedSeries = computed(() => {
    const selectedRaces = this.selectedRaces();
    const seriesIds = [...new Set(selectedRaces.map(race => race.seriesId))];
    const allSeries = this.raceStore.allSeries();
    return allSeries.filter(series => seriesIds.includes(series.id));
  });

  addRaceId = (raceId: string) =>
    this.manuallyAddedRaceIds.update(ids => {
      const next = new Set(ids);
      next.add(raceId);
      return next;
    });

  removeRaceId = (raceId: string) =>
    this.manuallyAddedRaceIds.update(ids => {
      const next = new Set(ids);
      next.delete(raceId);
      return next;
    });
}

function isScheduledToday(race: Race): boolean {
  return new Date(race.scheduledStart).toDateString() === new Date().toDateString();
}

function sortRacesByTimeThenIndex(a: Race, b: Race): number {
  return a.scheduledStart.getTime() - b.scheduledStart.getTime() || a.index - b.index;
}

import { MatDialog as MatDialog, MatDialogRef as MatDialogRef } from '@angular/material/dialog';

import { ConfirmDialog } from './confirm-dialog';
import {
  EntryConflictChoice,
  EntryConflictDialog,
  EntryConflictSummary,
} from './entry-conflict-dialog';
import { MessageDialog } from "./message-dialog";
import { UnsavedChangesChoice, UnsavedChangesDialog } from './unsaved-changes-dialog';
import {
  DiscardProfileDialogData,
  DiscardProfileEditDialog,
} from './discard-profile-edit-dialog';
import { inject, Injectable } from '@angular/core';
import { firstValueFrom, lastValueFrom } from 'rxjs';

@Injectable({
    providedIn: 'root',
})
export class DialogsService {
    private dialog = inject(MatDialog);

    public async confirm(title: string, message: string): Promise<boolean> {

        let dialogRef: MatDialogRef<ConfirmDialog>;

        dialogRef = this.dialog.open(ConfirmDialog);

        dialogRef.componentInstance.title = title;
        dialogRef.componentInstance.message = message;

        return lastValueFrom(dialogRef.afterClosed());
    }

    public async message(title: string, message: string): Promise<boolean> {

        let dialogRef: MatDialogRef<MessageDialog>;

        dialogRef = this.dialog.open(MessageDialog);

        dialogRef.componentInstance.title = title;
        dialogRef.componentInstance.message = message;

        return firstValueFrom(dialogRef.afterClosed());
    }

    public async promptEntryConflict(
        conflicts: EntryConflictSummary[],
    ): Promise<EntryConflictChoice> {
        const dialogRef = this.dialog.open<EntryConflictDialog, void, EntryConflictChoice>(
            EntryConflictDialog,
        );
        dialogRef.componentInstance.conflicts = conflicts;
        const result = await firstValueFrom(dialogRef.afterClosed());
        return result ?? 'cancel';
    }

    /** Opens the editor; resolves to stored **trigger** milestones (same as `Series.discards`), or undefined when cancelled. */
    public async editDiscardProfile(data: DiscardProfileDialogData): Promise<number[] | undefined> {
        const dialogRef = this.dialog.open(DiscardProfileEditDialog, {
            width: '560px',
            maxWidth: '95vw',
            data,
        });
        return await firstValueFrom(dialogRef.afterClosed());
    }

    public async promptUnsavedChanges(
        title = 'Unsaved changes',
        message = 'Save your edits before switching?'
    ): Promise<UnsavedChangesChoice> {
        let dialogRef: MatDialogRef<UnsavedChangesDialog, UnsavedChangesChoice>;
        dialogRef = this.dialog.open(UnsavedChangesDialog);
        dialogRef.componentInstance.title = title;
        dialogRef.componentInstance.message = message;
        const result = await firstValueFrom(dialogRef.afterClosed());
        return result ?? 'cancel';
    }
}

import { inject, Injectable } from '@angular/core';
import { MatDialog } from '@angular/material/dialog';
import { MatSnackBar } from '@angular/material/snack-bar';
import { firstValueFrom } from 'rxjs';
import { BoatsDupDialogData, BoatsDuplicatesDialog } from './boats-duplicates-dialog';
import { Boat, BoatsStore } from 'app/boats';

@Injectable({
  providedIn: 'root'
})
export class DuplicateBoatCheck {
  private snackbar = inject(MatSnackBar);
  private dialog = inject(MatDialog);
  private bs = inject(BoatsStore);

  async duplicateCheck(boat: Partial<Boat>, options?: { excludeBoatId?: string }): Promise<boolean> {
    const check = checkForDuplicateBoats(boat, this.bs.boats(), options);

    if (check.isDuplicate) {
      this.snackbar.open("Duplicate Boat exists in boat repository", "Dismiss", { duration: 4000 });
      return false;
    } else if (check.matches.length > 0) {
      return await this.showDialog(boat as Boat, check.matches);
    }
    return true;
  }

  async showDialog(boat: Boat, dups: Boat[]): Promise<boolean> {

    const dialogRef = this.dialog.open<BoatsDuplicatesDialog, BoatsDupDialogData>(BoatsDuplicatesDialog, {
      data: { boat: boat, possibleDuplicates: dups },
    });
    return firstValueFrom(dialogRef.afterClosed());
  }
}

/** Checks for duplicate boats, returning a list of boats that
 * match exactly and ones that are similar to.
 */
function checkForDuplicateBoats(
  newBoat: Partial<Boat>,
  allBoats: Boat[],
  options?: { excludeBoatId?: string }
): { isDuplicate: boolean, matches: Boat[]; } {
  const possibles = allBoats.filter(boat =>
    boat.id !== options?.excludeBoatId &&
    boat.boatClass === newBoat.boatClass &&
    boat.sailNumber === newBoat.sailNumber
  );

  const newName = (newBoat.name ?? '').trim().toLowerCase();
  const newHelm = (newBoat.helm ?? '').trim().toLowerCase();

  const isDuplicate = possibles.find(boat => {
    const existingName = (boat.name ?? '').trim().toLowerCase();
    const existingHelm = (boat.helm ?? '').trim().toLowerCase();
    // Primary identity is class + sail number + name.
    // If name is blank on either side, fall back to helm for backward compatibility.
    if (newName && existingName) {
      return existingName === newName;
    }
    return existingHelm.length > 0 && existingHelm === newHelm;
  }) !== undefined;

  return { isDuplicate, matches: possibles };
}

import { Injectable, inject } from '@angular/core';
import { RaceCalendarStore } from 'app/race-calender';
import {
  RaceCompetitorMutator,
  SeriesEntryIdentityConflictError,
} from 'app/results-input/services/race-competitor-mutator';
import { SeriesEntryStore } from 'app/results-input/services/series-entry-store';
import { ScoreSmarterError } from 'app/shared/utils/scoresmarter-error';
import { ClubStore } from '../../club-tenant';
import { Race } from '../../race-calender/model/race';
import { RaceCompetitor } from '../../results-input/model/race-competitor';
import { SeriesEntry } from '../../results-input/model/series-entry';
import { RaceCompetitorStore } from '../../results-input/services/race-competitor-store';
import { Handicap } from 'app/scoring/model/handicap';
import { PersonalHandicapBand } from 'app/scoring/model/personal-handicap';
import { SeriesEntryPartialUpdate } from 'app/results-input/services/series-entry-store';
import { resolveHandicapsForSeries } from './entry-helpers';
import {
  PerHullIdentity,
  describeIdentity,
  detectInRaceConflict,
  EntryConflictReason,
  findAllMatchingEntries,
} from 'app/results-input/services/series-entry-identity';

export interface EntryDetails {
  races: Race[];
  helm: string;
  crew?: string;
  boatClass: string;
  sailNumber: number;
  handicaps?: Handicap[];
  personalHandicapBand?: PersonalHandicapBand;
  /**
   * Tag ids to seed on a newly-created SeriesEntry. Typically `Boat.tags`
   * forwarded by the entry UI. Existing entries keep their tags - the RO
   * may have overridden them; this field is ignored on the reuse path.
   * Optional: omitted/undefined is treated as no boat tags (`[]`).
   */
  tags?: string[];
}

/**
 * A pre-existing race entry that prevents the proposed sign-on. Surfaced to
 * the UI so the user can choose to overwrite (boat-swap) or cancel; never
 * reported when the proposed entry can simply be added.
 */
export interface EntryConflict {
  race: Race;
  reason: EntryConflictReason;
  existingCompetitor: RaceCompetitor;
  existingEntry: SeriesEntry;
}

/**
 * Per-hull SeriesEntry creation.
 *
 * Each unique (boatClass, sailNumber, helm) tuple in a series corresponds to
 * exactly one SeriesEntry. The series-level `entryAlgorithm` only controls
 * how those entries are *merged at scoring time* into competitor groups (see
 * `mergeKeyFor`); it no longer affects how entries are created or how
 * duplicate sign-on is detected. This guarantees per-hull data (handicap,
 * boat class) is never overwritten when one helm sails multiple boats in
 * the same series.
 */
@Injectable({
  providedIn: 'root'
})
export class EntryService {
  private clubStore = inject(ClubStore);
  private raceResultsStore = inject(RaceCompetitorStore);
  private seriesEntryStore = inject(SeriesEntryStore);
  private raceCalanderStore = inject(RaceCalendarStore);
  private mutator = inject(RaceCompetitorMutator);

  /** Enter a race
   * throws a ScoreSmarterError exception if any conflict is detected.
   *
   * Callers that want to surface conflicts to the user (boat-swap UX) should
   * call `findEntryConflicts` first and, if appropriate, `swapAndEnter`. This
   * method is a strict guard for any caller that doesn't.
   */
  async enterRaces(details: EntryDetails): Promise<void> {

    const conflicts = this.findEntryConflicts(details);
    if (conflicts.length > 0) {
      throw new ScoreSmarterError(
        `Entry conflict for ${describeIdentity({
          boatClass: details.boatClass,
          sailNumber: details.sailNumber,
          helm: details.helm,
        })}`,
      );
    }

    for (const race of details.races) {
      const series = this.raceCalanderStore.allSeries().find(s => s.id === race.seriesId);
      if (!series) {
        const msg = 'EntryService: Series not found for race: ' + race.toString();
        console.error(msg);
        throw new ScoreSmarterError(msg);
      }

      const handicapsForEntry = resolveHandicapsForSeries(series, {
        boatClassName: details.boatClass,
        handicaps: details.handicaps,
        personalHandicapBand: details.personalHandicapBand,
        personalHandicapUnknown: !details.personalHandicapBand,
      }, this.clubStore.club().classes);

      const seriesEntryId =
        await this.findOrCreateSeriesEntry(race, details, handicapsForEntry);

      const competitor: Partial<RaceCompetitor> = {
        raceId: race.id,
        seriesId: race.seriesId,
        seriesEntryId,
        resultCode: 'NOT FINISHED',
      };

      await this.raceResultsStore.addResult(competitor);
    }
  }

  /**
   * Find every existing race entry that prevents the proposed sign-on across
   * the selected races. Each conflict is reported with its reason (exact-hull
   * duplicate, helm-already-in-race for merged-helm series, hull-already-in-
   * race for merged-hull series) so the caller can present a swap dialog.
   *
   * Joins each per-race competitor row to its SeriesEntry because identity
   * fields (helm/boatClass/sailNumber) live on the entry, not on the race
   * competitor.
   */
  findEntryConflicts(details: EntryDetails): EntryConflict[] {
    const incoming: PerHullIdentity = {
      boatClass: details.boatClass,
      sailNumber: details.sailNumber,
      helm: details.helm,
    };

    const entriesById = new Map(
      this.seriesEntryStore.selectedEntries().map(e => [e.id, e] as const),
    );
    const allComps = this.raceResultsStore.selectedCompetitors();
    const conflicts: EntryConflict[] = [];

    for (const race of details.races) {
      const series = this.raceCalanderStore.allSeries().find(s => s.id === race.seriesId);
      // Default to the strictest strategy if the series can't be located so
      // we never silently downgrade conflict detection.
      const strategy = series?.entryAlgorithm ?? 'classSailNumberHelm';

      for (const comp of allComps) {
        if (comp.raceId !== race.id) continue;
        const entry = entriesById.get(comp.seriesEntryId);
        if (!entry) continue;
        const reason = detectInRaceConflict(entry, incoming, strategy);
        if (reason) {
          conflicts.push({ race, reason, existingCompetitor: comp, existingEntry: entry });
        }
      }
    }

    return conflicts;
  }

  /**
   * Boat-swap path: delete every conflicting race competitor, then proceed
   * with the requested entry. The caller is expected to have already
   * obtained the user's consent via the conflict dialog.
   *
   * The deletion is per-race: an existing entry that is also used in OTHER
   * races stays put and only loses its row in the conflicting race(s).
   * Orphaned `SeriesEntry` documents are removed atomically by the mutator's
   * batched `deleteRaceCompetitor` (per-conflict authoritative orphan check).
   */
  async swapAndEnter(details: EntryDetails, conflicts: EntryConflict[]): Promise<void> {
    for (const conflict of conflicts) {
      await this.mutator.deleteRaceCompetitor(conflict.existingCompetitor);
    }

    // Re-evaluate after the deletions so we don't sign in twice if the same
    // race appeared in `conflicts` AND another later code path tries to add
    // it again. After the swap there must be no remaining conflicts; if there
    // are, the caller's view of the world was stale and we abort loudly.
    const remaining = this.findEntryConflicts(details);
    if (remaining.length > 0) {
      throw new ScoreSmarterError(
        `Boat swap could not clear all conflicts (${remaining.length} remaining). ` +
        `Refresh and try again.`,
      );
    }

    await this.enterRaces(details);
  }

  /**
   * Find an existing per-hull SeriesEntry (matched by boatClass + sailNumber +
   * helm) or create one. Updates the entry's handicaps/personalHandicapBand
   * to the latest input so they stay current; identity fields are preserved.
   */
  async findOrCreateSeriesEntry(race: Race, details: EntryDetails, handicaps: Handicap[]): Promise<string> {
    const seriesEntries = this.seriesEntryStore.selectedEntries()
      .filter(e => e.seriesId === race.seriesId);

    const identity: PerHullIdentity = {
      boatClass: details.boatClass,
      sailNumber: details.sailNumber,
      helm: details.helm,
    };
    const matches = findAllMatchingEntries(seriesEntries, identity);

    // Per-hull invariant: at most one SeriesEntry should ever match a given
    // (helm, boatClass, sailNumber). Detecting more than one means a previous
    // write (a rename, a manual Firestore edit, or a pre-refactor merge) has
    // corrupted the dataset. Refuse to write more results against either
    // entry until the duplicate is resolved.
    if (matches.length > 1) {
      throw new ScoreSmarterError(
        `Data integrity error: ${matches.length} SeriesEntries already match ` +
        `${describeIdentity(identity)} in series ${race.seriesId} ` +
        `(ids: ${matches.map(e => e.id).join(', ')}). ` +
        `Resolve the duplicate before continuing.`,
      );
    }

    const existing = matches[0];

    if (existing) {
      // Reuse path: refresh derived fields only. Tags are user-authored and
      // may have been overridden by an RO on the existing entry; do not
      // overwrite them with the incoming boat tags.
      //
      // `personalHandicapBand` is passed as `null` when the caller has no
      // band so the typed converter clears the field via `deleteField()`
      // on the partial write. Passing raw `undefined` would be *omitted*
      // by the converter (leave any stale band intact). The `null`
      // sentinel is part of the converter contract documented in
      // `firestore-helper.ts`.
      const entryUpdate: SeriesEntryPartialUpdate = {
        handicaps,
        personalHandicapBand: details.personalHandicapBand ?? null,
      };
      if (details.crew !== undefined && details.crew !== existing.crew) {
        entryUpdate.crew = details.crew;
      }
      await this.seriesEntryStore.updateEntry(existing.id, entryUpdate);
      return existing.id;
    }

    console.log(`EntryService: Adding series entry ${race.seriesName} index: ${race.index}`);

    try {
      return await this.mutator.createSeriesEntry({
        seriesId: race.seriesId,
        helm: details.helm,
        crew: details.crew,
        boatClass: details.boatClass,
        sailNumber: details.sailNumber,
        handicaps,
        personalHandicapBand: details.personalHandicapBand,
        tags: details.tags ?? [],
      });
    } catch (err) {
      // The mutator runs an authoritative collision check that may surface a
      // duplicate the cached `findAllMatchingEntries` above missed (e.g. a
      // concurrent sign-on, or a stale store snapshot). Translate it to the
      // same `ScoreSmarterError` shape callers already handle.
      if (err instanceof SeriesEntryIdentityConflictError) {
        throw new ScoreSmarterError(
          `Cannot create series entry: another entry already exists for ` +
          `${describeIdentity(identity)} in series ${race.seriesId} ` +
          `(id ${err.collidingEntryId}).`,
        );
      }
      throw err;
    }
  }
}

import { inject, Injectable } from '@angular/core';
import { collection, CollectionReference, doc, DocumentReference, Firestore } from '@angular/fire/firestore';
import { classInstanceConverter, dataObjectConverter } from '../../shared/firebase/firestore-helper';
import { ClubTenant } from './club-tenant';

@Injectable({
  providedIn: 'root'
})
export class FirestoreTenantService {
  private firestore = inject(Firestore);
  private clubContext = inject(ClubTenant);

  private get clubId(): string {
    const clubId = this.clubContext.clubId;
    if (!clubId) {
      // This will provide a clearer error if the service is used before the club context is ready.
      throw new Error('FirestoreTenantService: Club ID not available in context.');
    }
    return clubId;
  }

  /** Creates a typed DocumentReference for a document within the current club's tenant space. 
   * @param path Path segments of the document
  */
  docRef<T>(...path: string[]): DocumentReference<T> {
    return doc(this.firestore, 'clubs', this.clubId, ...path).withConverter(dataObjectConverter<T>());
  }

  /** Creates a typed CollectionReference for a sub-collection within the current club's tenant space. 
   * @param path Path of Firestore collection
  */
  collectionRef<T>(...path: string[]): CollectionReference<T> {
    return collection(this.firestore, 'clubs', this.clubId, ...path)
       .withConverter(dataObjectConverter<T>());
  }

  /** Creates a typed CollectionReference for a sub-collection of class instances within the current club's tenant space.
   * @param constructor Constructor for the class
   * @param path Path of Firestore collection
   */
  collectionOf<T>(constructor: new (data: Partial<T>) => T, ...path: string[]): CollectionReference<T> {
    return collection(this.firestore, 'clubs', this.clubId, ...path)
      .withConverter(classInstanceConverter<T>(constructor));
  }
}

import { Injectable } from '@angular/core';
import { Fleet } from '../model/fleet';
import { HandicapScheme } from 'app/scoring/model/handicap-scheme';
import { parseCsv, toCsv } from 'app/shared/utils/csv';

const COLUMNS = ['id', 'type', 'name', 'boatClassId', 'scheme', 'min', 'max', 'value'] as const;

export interface FleetsCsvParseResult {
  fleets: Partial<Fleet>[];
  errors: string[];
}

@Injectable({ providedIn: 'root' })
export class FleetsCsvService {
  buildCsv(fleets: Fleet[]): string {
    const rows = fleets.map(f => {
      const row: Record<string, string> = {
        id: f.id,
        type: f.type,
        name: (f as any).name ?? '',
        boatClassId: (f as any).boatClassId ?? '',
        scheme: (f as any).scheme ?? '',
        min: (f as any).min != null ? String((f as any).min) : '',
        max: (f as any).max != null ? String((f as any).max) : '',
        value: (f as any).value ?? '',
      };
      return row;
    });
    return toCsv([...COLUMNS], rows);
  }

  parseCsv(content: string): FleetsCsvParseResult {
    const parsed = parseCsv(content);
    const errors: string[] = [...parsed.errors];
    const headerColumns = parsed.header;
    if (headerColumns.length === 0) {
      return { fleets: [], errors: parsed.errors };
    }
    const missing = COLUMNS.filter(c => !headerColumns.includes(c));
    if (missing.length > 0) {
      return { fleets: [], errors: [`Missing required columns: ${missing.join(', ')}`] };
    }

    const fleets: Partial<Fleet>[] = [];
    for (let i = 0; i < parsed.rows.length; i++) {
      const record = parsed.rows[i];
      const rowResult = this.parseFleetRecord(record, i + 2);
      if (rowResult.error) {
        errors.push(rowResult.error);
      } else if (rowResult.fleet) {
        fleets.push(rowResult.fleet);
      }
    }
    return { fleets, errors };
  }

  private parseFleetRecord(
    record: Record<string, string>,
    lineNumber: number
  ): { fleet?: Partial<Fleet>; error?: string } {
    const rowErrors: string[] = [];
    const type = (record['type'] ?? '').trim() as Fleet['type'];
    const id = (record['id'] ?? '').trim();
    const name = (record['name'] ?? '').trim();
    const boatClassId = (record['boatClassId'] ?? '').trim();
    const scheme = (record['scheme'] ?? '').trim() as HandicapScheme;
    const minRaw = (record['min'] ?? '').trim();
    const maxRaw = (record['max'] ?? '').trim();
    const value = (record['value'] ?? '').trim();

    if (!type) {
      rowErrors.push('type is required');
    } else {
      switch (type) {
        case 'GeneralHandicap':
          // No extra fields needed
          break;
        case 'BoatClass':
          if (!boatClassId) rowErrors.push('boatClassId is required for BoatClass type');
          break;
        case 'HandicapRange':
          if (!name) rowErrors.push('name is required for HandicapRange type');
          if (!scheme) rowErrors.push('scheme is required for HandicapRange type');
          if (!minRaw) rowErrors.push('min is required for HandicapRange type');
          if (!maxRaw) rowErrors.push('max is required for HandicapRange type');
          break;
        case 'Tag':
          if (!name) rowErrors.push('name is required for Tag type');
          if (!value) rowErrors.push('value is required for Tag type');
          break;
        default:
          rowErrors.push(`Unknown fleet type: ${type}`);
      }
    }

    if (rowErrors.length > 0) {
      return {
        error: `Line ${lineNumber}: ${rowErrors.join('; ')}`,
      };
    }

    let fleet: any = { type, id };
    switch (type) {
      case 'GeneralHandicap':
        fleet.name = 'General Handicap';
        break;
      case 'BoatClass':
        fleet.boatClassId = boatClassId;
        break;
      case 'HandicapRange':
        fleet.name = name;
        fleet.scheme = scheme;
        fleet.min = Number(minRaw);
        fleet.max = Number(maxRaw);
        break;
      case 'Tag':
        fleet.name = name;
        fleet.value = value;
        break;
    }

    if (!id) delete fleet.id;
    return { fleet };
  }
}

import { Injectable, Injector, ProviderToken } from '@angular/core';

@Injectable({ providedIn: 'root' })
export class LazyInject {
   constructor(private injector: Injector) { }

   async get<T>(providerLoader: () => Promise<ProviderToken<T>>): Promise<T> {
      return this.injector.get(await providerLoader());
   }

   /**
    * Simplifies getting a provider from a dynamically imported module.
    * This is more type-safe than the basic `get` as it can infer the return
    * type and validate the provider name at compile time.
    * @param moduleLoader A function that returns a promise to a module, e.g., `() => import('@angular/material/dialog')`.
    * @param providerName The string name of the exported provider class/token from the module, e.g., `'MatDialog'`.
    */
   async getProvider<M, K extends keyof M>(
      moduleLoader: () => Promise<M>,
      providerName: K
   ): Promise<M[K] extends ProviderToken<infer I> ? I : never> {
      const module = await moduleLoader();
      const providerToken = module[providerName] as ProviderToken<any>;
      return this.injector.get(providerToken);
   }
}

import { Injectable, inject } from '@angular/core';
import { MatSnackBar } from '@angular/material/snack-bar';
import { Router } from '@angular/router';

@Injectable({
  providedIn: 'root'
})
export class LoginSnackbarService {

  private snackbar = inject(MatSnackBar);
  private router = inject(Router);

  target: string | undefined;

  open(message: string, target?: string) {
    const snackBarRef = this.snackbar.open(message, "Login", { duration: 3000 });

    snackBarRef.onAction().subscribe(() => {
      this.router.navigate(["/auth/login"]);
      this.target = target;
    });
  }
}

import { Injectable, inject } from '@angular/core';
import { ClubStore } from 'app/club-tenant';
import { Race, RaceCalendarStore } from 'app/race-calender';
import type { RaceStart } from 'app/race-calender/model/race-start';
import type { RaceStatus } from 'app/race-calender/model/race-status';
import { ResultCode } from 'app/scoring/model/result-code';
import { isFinishedComp } from 'app/scoring/model/result-code-scoring';
import { differenceInSeconds } from 'date-fns';
import { RaceCompetitor } from '../model/race-competitor';
import { ResolvedRaceCompetitor, sortResolvedCompetitors } from '../model/resolved-race-competitor';
import { RaceCompetitorMutator, type RaceScopedCompetitorPatch } from './race-competitor-mutator';
import { RaceCompetitorStore } from './race-competitor-store';
import { resolveStartTimeForEntry } from './race-start-resolver';
import { SeriesEntryStore } from './series-entry-store';

/**
 * View model used by the manual results table. Adds a derived `correctedTime`
 * to a `ResolvedRaceCompetitor`. Sorting and identity continue to come from
 * the underlying SeriesEntry.
 */
export class ExtendedRaceCompetitor extends ResolvedRaceCompetitor {
  correctedTime?: number;
  isSuspect?: boolean;
}

export interface ResultInput {
  finishTime: Date | null;
  laps: number;
  resultCode: ResultCode;
  position?: number | null;
}

/** Per-row editor state for pursuit / level-rating order entry UI */
export interface OrderEntryRowState {
  resultCode: ResultCode;
  /** Optional finish time for Level Rating (competitor info) */
  manualFinishTime?: Date | null;
  /** When set, overrides default sequential rank among finishers */
  rankOverride?: number | null;
}

export interface OrderEntryPersistInput {
  race: Race;
  /** All competitors for this race (from store) */
  competitors: RaceCompetitor[];
  /** Processed queue order (right pane), first = earliest processed */
  processedIds: string[];
  /** State keyed by competitor id for processed rows */
  rowState: Map<string, OrderEntryRowState>;
}

/**
 * Computes target manualPosition for finishers in processed order (ties share the same value).
 * Non-finishers (per isFinishedComp) get no rank (undefined).
 */
export function computeManualPositionsForOrderEntry(
  processedIds: string[],
  rowState: Map<string, OrderEntryRowState>
): Map<string, number | undefined> {
  const out = new Map<string, number | undefined>();
  let nextDefault = 1;
  for (const id of processedIds) {
    const row = rowState.get(id);
    if (!row) {
      out.set(id, undefined);
      continue;
    }
    const code = row.resultCode;
    if (!isFinishedComp(code)) {
      out.set(id, undefined);
      continue;
    }
    const ov = row.rankOverride;
    if (ov != null && !Number.isNaN(Number(ov))) {
      const p = Number(ov);
      out.set(id, p);
      nextDefault = Math.max(nextDefault, p + 1);
    } else {
      out.set(id, nextDefault);
      nextDefault++;
    }
  }
  return out;
}

/** One placing group: boats sharing the same rank (ties). */
export interface TieGroupRow {
  /** Hint from last compute — canonical rank comes from group order after normalize. */
  rank: number;
  ids: string[];
}

/** Split processed queue into placed finishers vs penalties / DNF (order preserved). */
export function segmentProcessedPlacedAndNonPlaced(
  processedIds: string[],
  rowState: Map<string, OrderEntryRowState>
): { placed: string[]; nonPlaced: string[] } {
  const placed: string[] = [];
  const nonPlaced: string[] = [];
  for (const id of processedIds) {
    const row = rowState.get(id);
    const code = row?.resultCode ?? 'NOT FINISHED';
    if (isFinishedComp(code)) {
      placed.push(id);
    } else {
      nonPlaced.push(id);
    }
  }
  return { placed, nonPlaced };
}

export function mergePlacedAndNonPlacedSegments(placed: string[], nonPlaced: string[]): string[] {
  return [...placed, ...nonPlaced];
}

/** Enforce placed segment first, then non-placed. */
export function enforceProcessedSegmentOrder(
  processedIds: string[],
  rowState: Map<string, OrderEntryRowState>
): string[] {
  const { placed, nonPlaced } = segmentProcessedPlacedAndNonPlaced(processedIds, rowState);
  return mergePlacedAndNonPlacedSegments(placed, nonPlaced);
}

/**
 * Consecutive placed finishers with the same effective rank form one tie group.
 */
export function buildTieGroupsFromPlaced(
  placedIds: string[],
  rowState: Map<string, OrderEntryRowState>
): TieGroupRow[] {
  if (placedIds.length === 0) return [];
  const positions = computeManualPositionsForOrderEntry(placedIds, rowState);
  const groups: TieGroupRow[] = [];
  let i = 0;
  while (i < placedIds.length) {
    const id = placedIds[i];
    const row = rowState.get(id);
    if (!row || !isFinishedComp(row.resultCode)) {
      i++;
      continue;
    }
    const p = positions.get(id);
    if (typeof p !== 'number') {
      i++;
      continue;
    }
    const block: string[] = [id];
    let j = i + 1;
    while (j < placedIds.length) {
      const nid = placedIds[j];
      const nrow = rowState.get(nid);
      if (!nrow || !isFinishedComp(nrow.resultCode)) break;
      const np = positions.get(nid);
      if (np !== p) break;
      block.push(nid);
      j++;
    }
    groups.push({ rank: p, ids: block });
    i = j;
  }
  return groups;
}

export function flattenTieGroups(groups: TieGroupRow[]): string[] {
  return groups.flatMap(g => g.ids);
}

/**
 * After reordering tie groups, assign rank 1..n; ties share rankOverride.
 */
export function normalizeRowStateFromOrderedTieGroups(
  orderedGroups: { ids: string[] }[],
  rowState: Map<string, OrderEntryRowState>
): Map<string, OrderEntryRowState> {
  const next = new Map(rowState);
  for (let i = 0; i < orderedGroups.length; i++) {
    const rank = i + 1;
    const ids = orderedGroups[i].ids;
    const shared = ids.length > 1;
    for (const id of ids) {
      const row = next.get(id);
      if (!row) continue;
      next.set(id, { ...row, rankOverride: shared ? rank : null });
    }
  }
  return next;
}

/**
 * Clear tie: clear rankOverride on id, then clear rankOverride on every following row that still has an override.
 */
export function clearTieRankOverrideChain(
  processedIds: string[],
  id: string,
  rowState: Map<string, OrderEntryRowState>
): Map<string, OrderEntryRowState> {
  const idx = processedIds.indexOf(id);
  if (idx < 0) return new Map(rowState);
  const next = new Map(rowState);
  const row = next.get(id);
  if (row) {
    next.set(id, { ...row, rankOverride: null });
  }
  for (let j = idx + 1; j < processedIds.length; j++) {
    const pid = processedIds[j];
    const r = next.get(pid);
    if (r?.rankOverride != null) {
      next.set(pid, { ...r, rankOverride: null });
    }
  }
  return next;
}

export interface CalculatedStats {
  elapsedSeconds: number;
  avgLapTime: number;
}

export type TimeRecordingMode = 'tod' | 'elapsed';

@Injectable({
  providedIn: 'root'
})
export class ManualResultsService {
  private readonly competitorStore = inject(RaceCompetitorStore);
  private readonly mutator = inject(RaceCompetitorMutator);
  private readonly raceStore = inject(RaceCalendarStore);
  private readonly seriesEntryStore = inject(SeriesEntryStore);
  private readonly clubStore = inject(ClubStore);

  private statusFromResultCodes(codes: ResultCode[]): RaceStatus | undefined {
    if (codes.length === 0) return undefined;
    const anyStarted = codes.some(code => code !== 'NOT FINISHED');
    if (!anyStarted) return undefined;
    const allCompleted = codes.every(code => code !== 'NOT FINISHED');
    return allCompleted ? 'Completed' : 'In progress';
  }

  /**
   * Calculates derived statistics for a result entry without persisting them.
   * This is useful for providing immediate feedback to the user in the UI.
   * @returns CalculatedStats or null if inputs are invalid.
   */
  calculateStats(finishTime: Date | null, laps: number, startTime: Date | undefined): CalculatedStats | null {
    if (!finishTime || !startTime || laps <= 0) {
      return null;
    }

    const elapsedSeconds = differenceInSeconds(finishTime, startTime);

    if (elapsedSeconds <= 0) {
      return null;
    }

    const avgLapTime = elapsedSeconds / laps;

    return { elapsedSeconds, avgLapTime };
  }

  /** Set start configuration
   * Sets the race start time, updating any results 
   * where the start time has already been set. 
  */
  async setStartTime(raceId: string, starts: RaceStart[], mode: TimeRecordingMode) {
    const primaryStart = starts[0]?.timeOfDay;

    await this.raceStore.updateRace(raceId, {
      actualStart: primaryStart,
      starts,
      timeInputMode: mode
    });

    const race = this.raceStore.allRaces().find(r => r.id === raceId);
    if (!race) return;

    const entries = await this.seriesEntryStore.getSeriesEntries(race.seriesId);
    const entryById = new Map(entries.map(e => [e.id, e] as const));
    const fleetsById = new Map(this.clubStore.club().fleets.map(f => [f.id, f] as const));

    const comps = this.competitorStore.selectedCompetitors().filter(comp => comp.raceId === raceId);
    const rows: { competitorId: string; patch: RaceScopedCompetitorPatch }[] = [];

    for (const comp of comps) {
      const entry = entryById.get(comp.seriesEntryId);
      if (!entry) continue;
      const resolvedStart = resolveStartTimeForEntry(entry, starts, fleetsById, primaryStart);
      if (!resolvedStart) continue;
      rows.push({ competitorId: comp.id, patch: { startTime: resolvedStart } });
    }

    if (rows.length > 0) {
      await this.mutator.updateRaceCompetitorsBulk(raceId, rows);
    }
  }

  /**
   * Processes and saves a single competitor's result.
   * It calculates derived values and updates the competitor in the store.
   */
  async recordResult(competitor: RaceCompetitor, race: Race, input: ResultInput): Promise<void> {
    const { finishTime, laps, resultCode, position } = input;

    const update: Partial<RaceCompetitor> = {
      resultCode: resultCode,
    };

    const starts = race.starts;
    const primaryStart = starts?.[0]?.timeOfDay ?? race.actualStart;
    if (primaryStart) {
      const entries = await this.seriesEntryStore.getSeriesEntries(race.seriesId);
      const entry = entries.find(e => e.id === competitor.seriesEntryId);
      const fleetsById = new Map(this.clubStore.club().fleets.map(f => [f.id, f] as const));
      update.startTime = entry
        ? (resolveStartTimeForEntry(entry, starts, fleetsById, primaryStart) ?? primaryStart)
        : primaryStart;
    }

    if (finishTime) {
      update.manualFinishTime = finishTime;
    }

    if (laps) {
      update.manualLaps = laps;
    }

    if (position) {
      update.manualPosition = position;
    }

    // Set a dirty flag on the race to indicate that its results have changed
    // and may need re-scoring. We can build on this later.
    if (!race.dirty) {
      await this.raceStore.updateRace(race.id, { dirty: true });
    }

    await this.competitorStore.updateResult(competitor.id, update);

    const raceCompetitors = this.competitorStore.selectedCompetitors().filter(c => c.raceId === race.id);
    const nextCodes = raceCompetitors.map(c => c.id === competitor.id ? resultCode : c.resultCode);
    const nextStatus = this.statusFromResultCodes(nextCodes);
    if (nextStatus && race.status !== nextStatus) {
      await this.raceStore.updateRace(race.id, { status: nextStatus });
    }
  }

  /**
   * Computes target manualPosition for finishers in processed order.
   * Non-finishers (per isFinishedComp) get no rank (undefined).
   */
  computeManualPositionsForOrderEntry(
    processedIds: string[],
    rowState: Map<string, OrderEntryRowState>
  ): Map<string, number | undefined> {
    return computeManualPositionsForOrderEntry(processedIds, rowState);
  }

  /**
   * Persists order-entry state with diff-only writes (manualPosition, resultCode, manualFinishTime).
   */
  async persistOrderEntryState(input: OrderEntryPersistInput): Promise<void> {
    const { race, competitors, processedIds, rowState } = input;
    const processedSet = new Set(processedIds);
    const positions = computeManualPositionsForOrderEntry(processedIds, rowState);

    const rows: { competitorId: string; patch: RaceScopedCompetitorPatch }[] = [];

    for (const comp of competitors) {
      const inProcessed = processedSet.has(comp.id);
      const row = rowState.get(comp.id);
      const targetCode: ResultCode = inProcessed && row ? row.resultCode : 'NOT FINISHED';

      const targetManualFinish: Date | undefined | null =
        inProcessed && row ? row.manualFinishTime ?? undefined : undefined;

      const targetMp =
        inProcessed && row && isFinishedComp(targetCode) ? positions.get(comp.id) : undefined;

      const patch: RaceScopedCompetitorPatch = {};

      if (comp.resultCode !== targetCode) {
        patch.resultCode = targetCode;
      }

      const prevTime = comp.manualFinishTime?.getTime();
      const nextTime = targetManualFinish instanceof Date ? targetManualFinish.getTime() : undefined;
      if (prevTime !== nextTime) {
        if (targetManualFinish === undefined || targetManualFinish === null) {
          if (prevTime !== undefined) {
            patch.manualFinishTime = null;
          }
        } else {
          patch.manualFinishTime = targetManualFinish;
        }
      }

      const prevMp = comp.manualPosition;
      if (targetMp === undefined) {
        if (prevMp !== undefined && prevMp !== null) {
          patch.manualPosition = null;
        }
      } else if (prevMp !== targetMp) {
        patch.manualPosition = targetMp;
      }

      if (Object.keys(patch).length > 0) {
        rows.push({ competitorId: comp.id, patch });
      }
    }

    const nextCodes: ResultCode[] = competitors.map(comp => {
      const inProcessed = processedSet.has(comp.id);
      const row = rowState.get(comp.id);
      return inProcessed && row ? row.resultCode : 'NOT FINISHED';
    });
    const nextStatus = this.statusFromResultCodes(nextCodes);

    if (rows.length === 0) {
      if (nextStatus && race.status !== nextStatus) {
        await this.raceStore.updateRace(race.id, { status: nextStatus });
      }
      return;
    }

    await this.mutator.updateRaceCompetitorsBulk(race.id, rows);

    if (nextStatus && race.status !== nextStatus) {
      await this.raceStore.updateRace(race.id, { status: nextStatus });
    }
  }
}

/** Sorts partially completed results
 * Unfinished competitors are placed at the top sorted by class/sail number
 * followed by finished competitors sorted by key value. 
 */
export function manualRaceTableSort(
  a: ResolvedRaceCompetitor,
  b: ResolvedRaceCompetitor,
  finishedOrder: keyof ExtendedRaceCompetitor,
  dir: 'asc' | 'desc' | ''
): number {

  const aAwaitingResult = a.resultCode === 'NOT FINISHED';
  const bAwaitingResult = b.resultCode === 'NOT FINISHED';

  if (aAwaitingResult !== bAwaitingResult) {
    // If one has a result and the other doesnt, one with no result goes first
    return aAwaitingResult ? -1 : 1;
  } else if (aAwaitingResult && bAwaitingResult) {
    // Neither have a result sort by class / boat
    return sortResolvedCompetitors(a, b);
  } else {
    // Both have a result, so sort them accordingly
    return sortCompetitorsWithResult(a, b, finishedOrder, dir);
  }
}

export function sortCompetitorsWithResult(
  a: ExtendedRaceCompetitor,
  b: ExtendedRaceCompetitor,
  finishedOrder: keyof ExtendedRaceCompetitor,
  dir: 'asc' | 'desc' | ''
): number {

  if ((a.resultCode === 'OK') !== (b.resultCode === 'OK')) {
    /* If one is OK and the other not put the OK first  */
    return (a.resultCode === 'OK') ? -1 : 1;
  } else {
    // Both competitors OK - order by specified parameter
    const valueA = a[finishedOrder];
    const valueB = b[finishedOrder];
    let ret = 0;

    if (valueA === undefined || valueA === null || valueB === undefined || valueB === null) {
      if (valueA === valueB) {
        ret = 0;
      } else {
        // If one is missing a value, place the one with a value first
        ret = (valueA === undefined || valueA === null) ? 1 : -1;
      }
    } else if (valueA instanceof Date && valueB instanceof Date) {
      ret = valueA.getTime() - valueB.getTime();
    } else if (typeof valueA === 'number') {
      ret = (valueA as number) - (valueB as number);
    } else if (typeof valueA === 'string') {
      ret = valueA.localeCompare(valueB as string);
    } else {
      console.error('ManualResultsPage: Unexpected sort order: ' + finishedOrder);
      ret = 0;
    }
    return (dir === 'asc') ? ret : -ret;
  }
}

import { Injectable } from '@angular/core';
import { Location } from '@angular/common';
import { Router, NavigationEnd } from '@angular/router';

@Injectable({ providedIn: 'root' })
export class NavigationService {
   private history: string[] = [];

   constructor(
      private router: Router,
      private location: Location
   ) {
      // Listen to router events of type NavigationEnd to
      // manage an app-specific navigation history.
      this.router.events.subscribe((event) => {
         if (event instanceof NavigationEnd) {
            this.history.push(event.urlAfterRedirects);
         }
      });
   }

   /**
    * Manage back navigation.
    */
   back(): void {
      this.history.pop();

      // If the history still contains entries after popping
      // the current URL off of the stack, we can safely
      // navigate back. Otherwise we're falling back to the
      // application root.
      if (this.history.length > 0) {
         console.log('navigating back');
         this.location.back();
      } else {
         console.log('navigating to /');
         this.router.navigateByUrl('/');
      }
   }
}

