import { computed, Injectable, Signal } from '@angular/core';
import { rxResource } from '@angular/core/rxjs-interop';
import { collectionData, getDoc, getDocs, query, where, writeBatch } from '@angular/fire/firestore';
import { generateSecureID } from 'app/shared/firebase/firestore-helper';
import { isSameDay } from 'date-fns';
import { map, Observable, tap } from 'rxjs';
import { Race } from '../model/race';
import { Series } from '../model/series';
import { RaceCalendarStoreBase, RaceSeriesDetails, seriesSort, sortRaces } from './race-calendar-store-base';

/** Service that returns the complete race calander 
 * Used for race calander administration and planning
 */
@Injectable({
   providedIn: 'root',
})
export class RaceCalendarStore extends RaceCalendarStoreBase {

   // Fetch only active series (not archived)
   private readonly seriesResource = rxResource<Series[], unknown>({
      stream: (): Observable<Series[]> =>
         collectionData(
            query(this.seriesCollection, where('archived', '==', false)),
            { idField: 'id' }
         ).pipe(
            map(seriesList =>
               [...seriesList]
                  .map(s => s)
                  .sort(seriesSort),
            ),
            tap(seriesList => console.log(`FullRaceCalander. Loaded ${seriesList.length} series`))
         ),
      defaultValue: [],
   });

   private readonly racesResource = rxResource<Race[], unknown>({
      stream: (): Observable<Race[]> =>
         collectionData(
            query(this.racesCollection, where('status', '!=', 'Archived')),
            { idField: 'id' }
         ).pipe(
            map(races => races.sort(sortRaces)),
            tap(races => console.log(`FullRaceCalander. Loaded ${races.length} races`))
         ),
      defaultValue: []
   });

   readonly allSeries = this.seriesResource.value.asReadonly();
   readonly isLoading = this.seriesResource.isLoading;
   readonly error = this.seriesResource.error;

   readonly allRaces = this.racesResource.value.asReadonly();
   readonly racesLoading = this.racesResource.isLoading;
   readonly racesError = this.racesResource.error;

   getSeries(id: Signal<string>): Signal<Series | undefined> {
      return computed(() => this.allSeries().find(s => s.id === id()));
   }

   getRace(id: Signal<string>): Signal<Race | undefined> {
      return computed(() => this.allRaces().find(s => s.id === id()));
   }

   getSeriesRaces(id: Signal<string>): Signal<Race[]> {
      return computed(() => this.allRaces().filter(s => s.seriesId === id()));
   }

   // Fallback fetch for a specific series if not in cache
   async getSeriesById(id: string): Promise<Series | undefined> {
      const currentSeries = this.allSeries().find(s => s.id === id);
      if (currentSeries) {
         return currentSeries;
      }

      // Fallback to fetching directly from Firestore
      const seriesDocRef = this.ref(id);
      const snapshot = await getDoc(seriesDocRef);
      return snapshot.exists() ? snapshot.data() : undefined;
   }

   // Fallback fetch for a specific race if not in cache
   async getRaceById(id: string): Promise<Race | undefined> {
      const currentRace = this.allRaces().find(r => r.id === id);
      if (currentRace) {
         return currentRace;
      }

      // Fallback to fetching directly from Firestore
      const raceDocRef = this.raceRef(id);
      const snapshot = await getDoc(raceDocRef);
      return snapshot.exists() ? { ...snapshot.data(), id: snapshot.id } : undefined;
   }

   /**
    * Marks the race as needing attention for scoring/publish workflows.
    * Skips the Firestore write when the race is already dirty (safe default, fewer writes).
    */
   async ensureRaceDirty(raceId: string): Promise<void> {
      const race = await this.getRaceById(raceId);
      if (!race) return;
      if (race.dirty === true) return;
      await this.updateRace(raceId, { dirty: true });
   }

   /**
    * Fetches all races for a series directly from Firestore.
    */
   async getSeriesRacesById(seriesId: string): Promise<Race[]> {
      const q = query(this.racesCollection, where('seriesId', '==', seriesId), where('status', '!=', 'Archived'));
      const snapshot = await getDocs(q);
      return snapshot.docs.map(doc => ({ ...doc.data(), id: doc.id })).sort(sortRaces);
   }

   /** Adds races to a specified series 
    *  Race indices and race-of-day are set based on date. 
   */
   async addRaces(seriesDetails: RaceSeriesDetails, races: Partial<Race>[]): Promise<void> {
      const existingRaces = this.allRaces().filter(r => r.seriesId === seriesDetails.id);

      // Create temporary IDs for sorting purposes for new races
      const newRacesWithIds = races.map((race, i) => ({ ...race, id: `new-${i}` })) as Race[];

      const allRacesForSeries = [...existingRaces, ...newRacesWithIds].sort(sortRaces);

      const batch = writeBatch(this.firestore);
      let dayCounter = 0;
      let lastDate: Date | null = null;

      allRacesForSeries.forEach((race, i) => {
         // Recalculate raceOfDay
         if (lastDate && isSameDay(race.scheduledStart, lastDate)) {
            dayCounter++;
         } else {
            dayCounter = 1;
         }
         lastDate = race.scheduledStart;

         const updatedRace: Partial<Race> = {
            ...race,
            index: i + 1,
            raceOfDay: dayCounter,
         };

         if (race.id.startsWith('new-')) {
            // This is a new race, add it to the batch
            const newId = generateSecureID(10000, `R-${seriesDetails.name}`);
            const newRaceRef = this.raceRef(newId);
            // Exclude the temporary id from the data being set
            const { id, ...raceData } = updatedRace;

            batch.set(newRaceRef, {
               ...raceData,
               seriesId: seriesDetails.id,
               seriesName: seriesDetails.name,
               status: 'Future',
            } as Partial<Race>);
         } else {
            // This is an existing race, update it in the batch
            const raceRef = this.raceRef(race.id);
            batch.update(raceRef, { index: updatedRace.index, raceOfDay: updatedRace.raceOfDay });
         }
      });

      // Update series dates
      if (allRacesForSeries.length > 0) {
         const dates = allRacesForSeries.map(r => r.scheduledStart.getTime());
         const startDate = new Date(Math.min(...dates));
         const endDate = new Date(Math.max(...dates));
         batch.update(this.ref(seriesDetails.id), { startDate, endDate });
      }

      await batch.commit();
   }

   /** Delete a race from a series, renumnbering the races are requied */
   override async deleteRace(raceToDelete: Race): Promise<void> {
      const remainingRaces = this.allRaces()
         .filter(r => r.seriesId === raceToDelete.seriesId && r.id !== raceToDelete.id)
         .sort(sortRaces);

      const batch = writeBatch(this.firestore);

      // First, delete the race
      batch.delete(this.raceRef(raceToDelete.id));

      // Then, update the indexes of the remaining races
      let dayCounter = 0;
      let lastDate: Date | null = null;
      remainingRaces.forEach((race, i) => {
         if (lastDate && isSameDay(race.scheduledStart, lastDate)) { dayCounter++; } else { dayCounter = 1; }
         lastDate = race.scheduledStart;
         const raceRef = this.raceRef(race.id);
         batch.update(raceRef, { index: i + 1, raceOfDay: dayCounter });
      });

      // Update series dates
      if (remainingRaces.length > 0) {
         const dates = remainingRaces.map(r => r.scheduledStart.getTime());
         const startDate = new Date(Math.min(...dates));
         const endDate = new Date(Math.max(...dates));
         batch.update(this.ref(raceToDelete.seriesId), { startDate, endDate });
      } else {
         batch.update(this.ref(raceToDelete.seriesId), { startDate: null, endDate: null });
      }

      await batch.commit();
   }

   /** Update a race and recalculate series dates if scheduledStart changed */
   override async updateRace(raceId: string, data: Partial<Race>): Promise<void> {
      const batch = writeBatch(this.firestore);
      batch.set(this.raceRef(raceId), data, { merge: true });

      if (data.scheduledStart) {
         const race = this.allRaces().find(r => r.id === raceId);
         if (race) {
            const allRacesForSeries = this.allRaces().filter(r => r.seriesId === race.seriesId);
            const updatedRaces = allRacesForSeries.map(r => r.id === raceId ? { ...r, ...data } as Race : r);

            const dates = updatedRaces.map(r => r.scheduledStart.getTime());
            if (dates.length > 0) {
               const startDate = new Date(Math.min(...dates));
               const endDate = new Date(Math.max(...dates));
               batch.update(this.ref(race.seriesId), { startDate, endDate });
            }
         }
      }

      await batch.commit();
   }
}

import { inject, Injectable } from '@angular/core';
import { generateSecureID } from 'app/shared/firebase/firestore-helper';
import { deleteDoc, getDocs, getFirestore, query, setDoc, where, writeBatch, Firestore } from '@angular/fire/firestore';
import { Race } from '../model/race';
import { Series } from '../model/series';
import { FirestoreTenantService } from 'app/club-tenant';

export interface RaceSeriesDetails {
  id: string;
  name: string;
  fleetId: string;
}

@Injectable({
  providedIn: 'root',
})
export class RaceCalendarStoreBase {
  protected readonly firestore = inject(Firestore);
  private readonly tenant = inject(FirestoreTenantService);

  protected ref = (id: string) => this.tenant.docRef<Series>('series', id);
  protected seriesCollection = this.tenant.collectionRef<Series>('series');

  protected raceRef = (id: string) => this.tenant.docRef<Race>('races', id);
  protected racesCollection = this.tenant.collectionRef<Race>('races');

  /** Add a series retruning a document Id */
  async addSeries(series: Partial<Series>): Promise<string> {
    series.archived = false;
    const id = generateSecureID(1000, `S-${series.name}`);
    await setDoc(this.ref(id), series);
    return id;
  }

  async updateSeries(id: string, data: Partial<Series>) {
    const scoringCriticalFields: (keyof Series)[] = [
      'scoringAlgorithm',
      'entryAlgorithm',
      'discards',
      'primaryScoringConfiguration',
      'secondaryScoringConfigurations'
    ];

    const hasScoringChange = scoringCriticalFields.some(field => field in data);
    if (hasScoringChange) {
      data.dirty = true;
    }

    await setDoc(this.ref(id), data, { merge: true });
  }

  async deleteSeries(id: string) {
    // Delete races for the series. 
    const racesSnapshot = await getDocs(query(this.racesCollection, where('seriesId', '==', id)));

    const batch = writeBatch(this.firestore);
    racesSnapshot.forEach(doc => batch.delete(doc.ref));

    // Delete the series in the batch
    batch.delete(this.ref(id));
    await batch.commit();
  }

  async addRace(seriesDetails: RaceSeriesDetails, race: Partial<Race>): Promise<void> {
    race.seriesId = seriesDetails.id;
    race.seriesName = seriesDetails.name;
    race.fleetId = seriesDetails.fleetId;
    race.status = 'Future';
    const id = generateSecureID(10000, `R-${seriesDetails.name}`);
    await setDoc(this.raceRef(id), race);
  }

  async updateRace(raceId: string, data: Partial<Race>): Promise<void> {
    await setDoc(this.raceRef(raceId), data, { merge: true });
  }

  async deleteRace(race: Race): Promise<void> {
    await deleteDoc(this.raceRef(race.id));
  }
}

export function seriesSort(a: Series, b: Series): number {
  if (!a.startDate) {
    return !b.startDate ? 1 : 0;
  }

  if (!b.startDate) {
    return -1;
  }

  const ret = a.startDate.getTime() - b.startDate.getTime();
  if (ret !== 0) {
    return ret;
  } else {
    return a.name.localeCompare(b.name);
  }
}

export function sortRaces(a: Race, b: Race): number {
  const ret = a.scheduledStart.getTime() - b.scheduledStart.getTime();

  if (ret === 0) {
    return a.raceOfDay - b.raceOfDay;
  } else {
    return ret;
  }
}

import { Injectable, inject } from '@angular/core';
import { ClubStore } from 'app/club-tenant';
import { resolveHandicapsForSeries } from 'app/entry/services/entry-helpers';
import { RaceCalendarStore } from 'app/race-calender';
import { Handicap, getHandicapValue } from 'app/scoring/model/handicap';
import { PersonalHandicapBand } from 'app/scoring/model/personal-handicap';
import { ScoreSmarterError } from 'app/shared/utils/scoresmarter-error';
import { RaceCompetitor } from '../model/race-competitor';
import { SeriesEntry } from '../model/series-entry';
import {
  RaceCompetitorMutator,
  SeriesEntryIdentityConflictError,
} from './race-competitor-mutator';
import { RaceCompetitorStore } from './race-competitor-store';
import {
  PerHullIdentity,
  describeIdentity,
  detectInRaceConflict,
  findCollidingEntry,
} from './series-entry-identity';
import { SeriesEntryStore } from './series-entry-store';

/**
 * Per-race overrides are now intentionally minimal. Only `crew` may differ
 * between races for the same hull (handled via `RaceCompetitor.crewOverride`).
 * Every other piece of identity / boat / handicap data lives on the
 * `SeriesEntry` and is therefore inherently series-wide.
 */
export type CrewEditScope = 'raceOnly' | 'wholeSeries';

export type EditOperation =
  | { type: 'setHelm'; value: string }
  | { type: 'setCrew'; value: string; scope: CrewEditScope }
  | { type: 'setBoatClass'; value: string }
  | { type: 'setSailNumber'; value: number }
  | { type: 'setHandicap'; scheme: Handicap['scheme']; value: number }
  | { type: 'setPersonalHandicapBand'; band: PersonalHandicapBand | undefined }
  | { type: 'deleteCompetitor' };

export interface EditRaceCompetitorCommand {
  competitorId: string;
  operation: EditOperation;
}

/**
 * Single-shot edit of every correctable `SeriesEntry` field plus crew.
 * Handicaps are not part of this payload: they are re-resolved from the new
 * class / personal band via `resolveHandicapsForSeries` when those change.
 *
 * `crewScope`: `raceOnly` updates `RaceCompetitor.crewOverride` for this
 * race; `wholeSeries` updates `SeriesEntry.crew` (the post-entry correction
 * form always sends `raceOnly`).
 *
 * Intended for the post-entry correction dialog; the per-operation
 * `EditRaceCompetitorCommand` + `apply()` path remains for other callers.
 */
export interface SeriesEntryEditCommand {
  competitorId: string;
  helm: string;
  crew: string;
  crewScope: CrewEditScope;
  boatClass: string;
  sailNumber: number;
  personalHandicapBand?: PersonalHandicapBand;
  /**
   * User-authored tags for the entry. Omitted means "leave tags unchanged"
   * so legacy callers don't reset them on save.
   */
  tags?: string[];
}

/**
 * Applies edit commands originating from the per-race UI. Logic intentionally
 * isolates per-race scope (only the crew field) from per-hull scope (everything
 * else); see `EditOperation` for the strict allowed shapes.
 */
@Injectable({ providedIn: 'root' })
export class RaceCompetitorEditService {
  private readonly competitors = inject(RaceCompetitorStore);
  private readonly seriesEntries = inject(SeriesEntryStore);
  private readonly raceCalendar = inject(RaceCalendarStore);
  private readonly clubStore = inject(ClubStore);
  private readonly mutator = inject(RaceCompetitorMutator);

  async apply(command: EditRaceCompetitorCommand): Promise<void> {
    const target = this.competitors.selectedCompetitors().find(c => c.id === command.competitorId);
    if (!target) {
      throw new Error(`Competitor not found: ${command.competitorId}`);
    }
    const entry = this.seriesEntries.selectedEntries().find(e => e.id === target.seriesEntryId);
    if (!entry) {
      throw new Error(`SeriesEntry ${target.seriesEntryId} not found for competitor ${target.id}`);
    }

    switch (command.operation.type) {
      case 'deleteCompetitor':
        await this.deleteCompetitor(target);
        return;
      case 'setCrew':
        await this.applyCrew(target, entry, command.operation);
        return;
      case 'setHelm':
      case 'setBoatClass':
      case 'setSailNumber':
      case 'setHandicap':
      case 'setPersonalHandicapBand':
        await this.applyEntryChange(entry, command.operation);
        return;
    }
  }

  private async applyCrew(
    target: RaceCompetitor,
    entry: SeriesEntry,
    op: Extract<EditOperation, { type: 'setCrew' }>,
  ): Promise<void> {
    const trimmed = op.value.trim();
    if (op.scope === 'raceOnly') {
      // crewOverride === undefined means "use entry crew"; we keep the empty
      // string as an explicit override that clears the entry crew for this race.
      const next = trimmed === (entry.crew ?? '') ? undefined : trimmed;
      if ((target.crewOverride ?? null) === (next ?? null)) return;
      await this.competitors.updateResult(target.id, { crewOverride: next });
      return;
    }

    if ((entry.crew ?? '') !== trimmed) {
      await this.seriesEntries.updateEntry(entry.id, { crew: trimmed });
    }
    // Wholeseries: drop any per-race overrides for this entry that now match
    // the new entry crew. We deliberately do NOT touch overrides that still
    // diverge from the new entry crew.
    const allForEntry = this.competitors.selectedCompetitors().filter(c => c.seriesEntryId === entry.id);
    for (const comp of allForEntry) {
      if (comp.crewOverride !== undefined && comp.crewOverride === trimmed) {
        await this.competitors.updateResult(comp.id, { crewOverride: undefined });
      }
    }
  }

  private async applyEntryChange(
    entry: SeriesEntry,
    op: Exclude<EditOperation, { type: 'setCrew' | 'deleteCompetitor' }>,
  ): Promise<void> {
    // Per-hull identity uniqueness is enforced authoritatively by the
    // mutator (it queries series-entries and throws
    // SeriesEntryIdentityConflictError on collision). We translate that to
    // the friendly rename message expected by callers.
    const update: Partial<SeriesEntry> = {};
    switch (op.type) {
      case 'setHelm':
        if (entry.helm === op.value) return;
        update.helm = op.value;
        break;
      case 'setBoatClass':
        if (entry.boatClass === op.value) return;
        update.boatClass = op.value;
        break;
      case 'setSailNumber':
        if (entry.sailNumber === op.value) return;
        update.sailNumber = op.value;
        break;
      case 'setHandicap': {
        const current = getHandicapValue(entry.handicaps, op.scheme);
        if (current === op.value) return;
        const without = (entry.handicaps ?? []).filter(h => h.scheme !== op.scheme);
        update.handicaps = [...without, { scheme: op.scheme, value: op.value }];
        break;
      }
      case 'setPersonalHandicapBand':
        // UI uses `undefined` for unknown; persisted clear is explicit `null` (merge → deleteField).
        if ((entry.personalHandicapBand ?? null) === (op.band ?? null)) return;
        (update as { personalHandicapBand?: PersonalHandicapBand | null }).personalHandicapBand =
          op.band === undefined ? null : op.band;
        break;
    }
    if (Object.keys(update).length === 0) return;

    const next: SeriesEntry = { ...entry, ...update } as SeriesEntry;
    try {
      await this.mutator.updateSeriesEntryFromEdit(entry, next);
    } catch (err) {
      if (err instanceof SeriesEntryIdentityConflictError) {
        throw new ScoreSmarterError(
          `Cannot rename: another series entry already exists for ` +
          `${describeIdentity(err.identity)} (id ${err.collidingEntryId}). ` +
          `Delete or merge that entry before renaming.`,
        );
      }
      throw err;
    }
  }

  private async deleteCompetitor(target: RaceCompetitor): Promise<void> {
    await this.mutator.deleteRaceCompetitor(target);
  }

  /**
   * Single-shot multi-field edit from the post-entry correction dialog.
   *
   * Steps, in order, so that we never half-apply a change:
   * 1. Resolve competitor + entry + series.
   * 2. Build the proposed identity tuple and run duplicate + in-race
   *    conflict checks against the *final* (helm, class, sail).
   * 3. Persist crew using its scope rule (race override vs entry).
   * 4. Recompute handicaps/tags for the new class / band, then write every
   *    changed entry field in one `updateEntry` call.
   * 5. Mark affected races dirty so the existing guards republish on leave.
   */
  async applyEdit(command: SeriesEntryEditCommand): Promise<void> {
    const target = this.competitors.selectedCompetitors().find(c => c.id === command.competitorId);
    if (!target) {
      throw new Error(`Competitor not found: ${command.competitorId}`);
    }
    const entry = this.seriesEntries.selectedEntries().find(e => e.id === target.seriesEntryId);
    if (!entry) {
      throw new Error(`SeriesEntry ${target.seriesEntryId} not found for competitor ${target.id}`);
    }
    const series = this.raceCalendar.allSeries().find(s => s.id === entry.seriesId);
    if (!series) {
      throw new Error(`Series ${entry.seriesId} not found for entry ${entry.id}`);
    }

    const helm = command.helm.trim();
    const crew = command.crew.trim();
    const boatClass = command.boatClass.trim();
    const sailNumber = command.sailNumber;

    const proposed: PerHullIdentity = { helm, boatClass, sailNumber };

    // Same series: another SeriesEntry with this (helm, class, sail) tuple.
    // If it exists, we either error (already represented in this race), run
    // merged-hull/helm checks, then re-point this race row at that entry
    // (same model as EntryService.findOrCreateSeriesEntry on reuse), or — if
    // there is no collision — rename the current entry in place.
    const sameSeriesEntries = this.seriesEntries
      .selectedEntries()
      .filter(e => e.seriesId === entry.seriesId);
    const collision = findCollidingEntry(sameSeriesEntries, proposed, entry.id);
    if (collision) {
      const alreadyInThisRace = this.competitors
        .selectedCompetitors()
        .some(
          c =>
            c.raceId === target.raceId &&
            c.id !== target.id &&
            c.seriesEntryId === collision.id,
        );
      if (alreadyInThisRace) {
        throw new ScoreSmarterError(
          `${describeIdentity(proposed)} is already entered in this race.`,
        );
      }
    }

    // In-race conflict against other competitors in the same race under the
    // series' entry strategy (helm-in-race / hull-in-race). A no-op identity
    // would match the target itself, so we exclude its own competitor row.
    const currentRaceComps = this.competitors
      .selectedCompetitors()
      .filter(c => c.raceId === target.raceId && c.id !== target.id);
    const strategy = series.entryAlgorithm ?? 'classSailNumberHelm';
    for (const comp of currentRaceComps) {
      const otherEntry = this.seriesEntries.selectedEntries().find(e => e.id === comp.seriesEntryId);
      if (!otherEntry) continue;
      const reason = detectInRaceConflict(otherEntry, proposed, strategy);
      if (reason) {
        throw new ScoreSmarterError(
          `Cannot update: ${describeIdentity(proposed)} would conflict with ` +
          `${describeIdentity(otherEntry)} in this race (${reason}).`,
        );
      }
    }

    let workingEntry = entry;
    let competitorForCrew = target;
    if (collision) {
      // Atomic repoint + orphan-cleanup of the now-unused old entry. The
      // mutator validates the target entry belongs to the same series.
      await this.mutator.repointRaceCompetitorToEntry(target, collision.id, {
        cleanupOldEntry: 'ifOrphan',
      });
      workingEntry = collision;
      const refreshed = this.competitors.selectedCompetitors().find(c => c.id === target.id);
      // Live store may not yet reflect the write; fall back to a synthesised
      // row whose `seriesEntryId` matches the new target so crew-scope
      // comparisons against `workingEntry` stay correct.
      competitorForCrew = refreshed ?? new RaceCompetitor({ ...target, seriesEntryId: collision.id });
    }

    // Crew: the only field with per-race scope. We apply it first so a
    // downstream entry-write failure can't leave the race row mutated in a
    // way that contradicts the entry's crew.
    const crewScopeChanged = await this.applyCrewEdit(
      competitorForCrew,
      workingEntry,
      crew,
      command.crewScope,
    );

    // Entry field changes. Handicaps are re-resolved *only* when the boat
    // class or personal band actually changed; a bare helm/crew correction
    // must not silently rewrite handicaps and republish every race in the
    // series.
    /** When absent, callers are not intending to edit the saved band — avoid spurious clears. */
    const commandSpecifiesBand = Object.prototype.hasOwnProperty.call(command, 'personalHandicapBand');
    const personalHandicapBand = command.personalHandicapBand;
    const classChanged = workingEntry.boatClass !== boatClass;
    const bandChanged =
      commandSpecifiesBand &&
      (workingEntry.personalHandicapBand ?? undefined) !== (personalHandicapBand ?? undefined);

    const entryUpdate: Partial<SeriesEntry> = {};
    if (workingEntry.helm !== helm) entryUpdate.helm = helm;
    if (classChanged) entryUpdate.boatClass = boatClass;
    if (workingEntry.sailNumber !== sailNumber) entryUpdate.sailNumber = sailNumber;
    if (bandChanged) {
      (entryUpdate as { personalHandicapBand?: PersonalHandicapBand | null }).personalHandicapBand =
        personalHandicapBand === undefined ? null : personalHandicapBand;
    }

    if (classChanged || bandChanged) {
      // When the hull's class changes, do not pass the old `workingEntry.handicaps`
      // into the resolver: valid PY (etc.) on the entry are treated as user
      // overrides and would otherwise stick to the previous class's numbers.
      // A class change means "take handicaps from the new club class (+ band
      // rules)" — same as the entry form preview. Band-only edits keep the
      // existing handicap array so PY-based Personal math stays stable.
      const recomputed = resolveHandicapsForSeries(
        series,
        {
          boatClassName: boatClass,
          handicaps: classChanged ? undefined : workingEntry.handicaps,
          personalHandicapBand,
          personalHandicapUnknown: !personalHandicapBand,
        },
        this.clubStore.club().classes,
      );
      if (!handicapsEqual(workingEntry.handicaps, recomputed)) {
        entryUpdate.handicaps = recomputed;
      }
    }

    // User-tag edits flow through `command.tags`. When omitted we keep
    // the existing tags; when supplied we replace them wholesale.
    if (command.tags !== undefined) {
      const nextTags = [...command.tags];
      if (!tagsEqual(workingEntry.tags, nextTags)) {
        entryUpdate.tags = nextTags;
      }
    }

    const entryChanged = Object.keys(entryUpdate).length > 0;
    if (entryChanged) {
      const next: SeriesEntry = { ...workingEntry, ...entryUpdate } as SeriesEntry;
      try {
        await this.mutator.updateSeriesEntryFromEdit(workingEntry, next);
      } catch (err) {
        if (err instanceof SeriesEntryIdentityConflictError) {
          throw new ScoreSmarterError(
            `Cannot update: another series entry already exists for ` +
            `${describeIdentity(err.identity)} (id ${err.collidingEntryId}).`,
          );
        }
        throw err;
      }
    }

    // Dirty marking: every race that references this entry is now stale for
    // series-scope changes. For a pure race-only crew edit we only touch the
    // current race. The set is always a superset of the current race when
    // any entry field changed.
    const raceIdsToMark = new Set<string>();
    if (collision) {
      raceIdsToMark.add(target.raceId);
    }
    if (crewScopeChanged === 'race') {
      raceIdsToMark.add(target.raceId);
    }
    if (entryChanged || crewScopeChanged === 'series') {
      for (const comp of this.competitors.selectedCompetitors()) {
        if (comp.seriesEntryId === workingEntry.id) raceIdsToMark.add(comp.raceId);
      }
    }
    for (const raceId of raceIdsToMark) {
      await this.raceCalendar.updateRace(raceId, { dirty: true });
    }
  }

  /**
   * Returns `'race'` when only the current `RaceCompetitor.crewOverride` was
   * touched, `'series'` when the entry crew was written, or `null` when the
   * value was already in sync with the selected scope.
   */
  private async applyCrewEdit(
    target: RaceCompetitor,
    entry: SeriesEntry,
    crew: string,
    scope: CrewEditScope,
  ): Promise<'race' | 'series' | null> {
    if (scope === 'raceOnly') {
      // `undefined` means "use the entry crew"; a deliberate empty string
      // override clears the entry crew for this race only.
      const next = crew === (entry.crew ?? '') ? undefined : crew;
      if ((target.crewOverride ?? null) === (next ?? null)) return null;
      await this.competitors.updateResult(target.id, { crewOverride: next });
      return 'race';
    }

    let changed = false;
    if ((entry.crew ?? '') !== crew) {
      await this.seriesEntries.updateEntry(entry.id, { crew });
      changed = true;
    }
    // Drop per-race overrides that now equal the new entry crew; we keep
    // overrides that still intentionally diverge.
    const allForEntry = this.competitors.selectedCompetitors().filter(c => c.seriesEntryId === entry.id);
    for (const comp of allForEntry) {
      if (comp.crewOverride !== undefined && comp.crewOverride === crew) {
        await this.competitors.updateResult(comp.id, { crewOverride: undefined });
        changed = true;
      }
    }
    return changed ? 'series' : null;
  }
}

function handicapsEqual(a: Handicap[] | undefined, b: Handicap[] | undefined): boolean {
  const ax = [...(a ?? [])].sort((x, y) => x.scheme.localeCompare(y.scheme));
  const bx = [...(b ?? [])].sort((x, y) => x.scheme.localeCompare(y.scheme));
  if (ax.length !== bx.length) return false;
  for (let i = 0; i < ax.length; i++) {
    if (ax[i].scheme !== bx[i].scheme || ax[i].value !== bx[i].value) return false;
  }
  return true;
}

function tagsEqual(a: string[] | undefined, b: string[] | undefined): boolean {
  const ax = [...(a ?? [])].sort();
  const bx = [...(b ?? [])].sort();
  if (ax.length !== bx.length) return false;
  return ax.every((t, i) => t === bx[i]);
}

import { inject, Injectable } from '@angular/core';
import { Firestore, setDoc, writeBatch } from '@angular/fire/firestore';
import { RaceCalendarStore } from 'app/race-calender';
import { Handicap } from 'app/scoring/model/handicap';
import { PersonalHandicapBand } from 'app/scoring/model/personal-handicap';
import { ResultCode } from 'app/scoring/model/result-code';
import { generateSecureID } from 'app/shared/firebase/firestore-helper';
import { ScoreSmarterError } from 'app/shared/utils/scoresmarter-error';
import { RaceCompetitor } from '../model/race-competitor';
import { SeriesEntry } from '../model/series-entry';
import { RaceCompetitorStore } from './race-competitor-store';
import {
  describeIdentity,
  findCollidingEntry,
  PerHullIdentity,
} from './series-entry-identity';
import { SeriesEntryStore } from './series-entry-store';

/**
 * Thrown when a series-entry write would create or leave two entries with the
 * same per-hull identity in one series. Callers (sign-on, edit) decide whether
 * to surface this to the user or repoint via `repointRaceCompetitorToEntry`.
 */
export class SeriesEntryIdentityConflictError extends ScoreSmarterError {
  readonly collidingEntryId: string;
  readonly seriesId: string;
  readonly identity: PerHullIdentity;
  constructor(collidingEntryId: string, seriesId: string, identity: PerHullIdentity) {
    super(
      `Series entry conflict: ${describeIdentity(identity)} already exists in series ` +
      `${seriesId} (entry id ${collidingEntryId}).`,
    );
    this.name = 'SeriesEntryIdentityConflictError';
    this.collidingEntryId = collidingEntryId;
    this.seriesId = seriesId;
    this.identity = identity;
  }
}

export interface RaceScopedCompetitorPatch {
  crewOverride?: string | null;
  recordedFinishTime?: Date | null;
  manualFinishTime?: Date | null;
  manualLaps?: number;
  manualPosition?: number | null;
  startTime?: Date | null;
  resultCode?: ResultCode;
}

export interface CreateSeriesEntryInput {
  seriesId: string;
  helm: string;
  boatClass: string;
  sailNumber: number;
  crew?: string;
  handicaps: Handicap[];
  personalHandicapBand?: PersonalHandicapBand;
  /** Tag ids to seed on the new entry; caller passes `[]` when none. */
  tags: string[];
}

const RACE_PATCH_KEYS: (keyof RaceScopedCompetitorPatch)[] = [
  'crewOverride',
  'recordedFinishTime',
  'manualFinishTime',
  'manualLaps',
  'manualPosition',
  'startTime',
  'resultCode',
];

function mergePayloadFromRacePatch(patch: RaceScopedCompetitorPatch): Partial<RaceCompetitor> {
  const out: Partial<RaceCompetitor> = {};
  for (const k of RACE_PATCH_KEYS) {
    if (!(k in patch)) continue;
    const v = patch[k as keyof RaceScopedCompetitorPatch];
    if (v === undefined) continue;
    (out as Record<string, unknown>)[k] = v;
  }
  return out;
}

function handicapListsEqual(a: Handicap[] | undefined, b: Handicap[] | undefined): boolean {
  const ax = [...(a ?? [])].sort((x, y) => x.scheme.localeCompare(y.scheme));
  const bx = [...(b ?? [])].sort((x, y) => x.scheme.localeCompare(y.scheme));
  if (ax.length !== bx.length) return false;
  for (let i = 0; i < ax.length; i++) {
    if (ax[i].scheme !== bx[i].scheme || ax[i].value !== bx[i].value) return false;
  }
  return true;
}

function tagListsEqual(a: string[] | undefined, b: string[] | undefined): boolean {
  const ax = [...(a ?? [])].sort();
  const bx = [...(b ?? [])].sort();
  if (ax.length !== bx.length) return false;
  return ax.every((t, i) => t === bx[i]);
}

/** True when persisted entry fields match (including optional band as null vs absent). */
function seriesEntriesEqual(a: SeriesEntry, b: SeriesEntry): boolean {
  return (
    a.id === b.id &&
    a.seriesId === b.seriesId &&
    a.helm === b.helm &&
    (a.crew ?? '') === (b.crew ?? '') &&
    (a.club ?? '') === (b.club ?? '') &&
    a.boatClass === b.boatClass &&
    a.sailNumber === b.sailNumber &&
    (a.personalHandicapBand ?? null) === (b.personalHandicapBand ?? null) &&
    handicapListsEqual(a.handicaps, b.handicaps) &&
    tagListsEqual(a.tags, b.tags)
  );
}

@Injectable({ providedIn: 'root' })
export class RaceCompetitorMutator {
  private readonly firestore = inject(Firestore);
  private readonly raceCompetitors = inject(RaceCompetitorStore);
  private readonly seriesEntries = inject(SeriesEntryStore);
  private readonly raceCalendar = inject(RaceCalendarStore);

  private async runInBatch(work: (batch: ReturnType<typeof writeBatch>) => void | Promise<void>): Promise<void> {
    const batch = writeBatch(this.firestore);
    await Promise.resolve(work(batch));
    await batch.commit();
  }

  // --- Race-scoped writes ----------------------------------------------------

  /**
   * Single merge write: `setDoc` is enough (no transaction with other docs).
   * Multi-row updates use `writeBatch` in `updateRaceCompetitorsBulk`.
   */
  async updateRaceCompetitor(competitorId: string, patch: RaceScopedCompetitorPatch): Promise<void> {
    const mergePayload = mergePayloadFromRacePatch(patch);
    if (Object.keys(mergePayload).length === 0) return;

    await setDoc(
      this.raceCompetitors.raceResultDocRef(competitorId),
      mergePayload as RaceCompetitor,
      { merge: true },
    );

    const comp = this.raceCompetitors.selectedCompetitors().find(c => c.id === competitorId);
    if (comp) {
      await this.raceCalendar.ensureRaceDirty(comp.raceId);
    }
  }

  /**
   * Per-row race-scoped merges for one race in one atomic batch.
   * Validates each competitor belongs to `raceId`.
   */
  async updateRaceCompetitorsBulk(
    raceId: string,
    rows: { competitorId: string; patch: RaceScopedCompetitorPatch }[],
  ): Promise<void> {
    if (rows.length === 0) return;

    const selected = this.raceCompetitors.selectedCompetitors();
    let wroteAny = false;
    await this.runInBatch(batch => {
      for (const { competitorId, patch } of rows) {
        const comp = selected.find(c => c.id === competitorId);
        if (!comp || comp.raceId !== raceId) {
          throw new ScoreSmarterError(
            `RaceCompetitorMutator: competitor ${competitorId} not in race ${raceId} or not in current selection.`,
          );
        }
        const mergePayload = mergePayloadFromRacePatch(patch);
        if (Object.keys(mergePayload).length === 0) continue;
        wroteAny = true;
        batch.set(this.raceCompetitors.raceResultDocRef(competitorId), mergePayload as RaceCompetitor, {
          merge: true,
        });
      }
    });

    if (wroteAny) {
      await this.raceCalendar.ensureRaceDirty(raceId);
    }
  }

  // --- Series-entry writes (per-hull uniqueness enforced) --------------------

  /**
   * Create a SeriesEntry, refusing if another entry in the same series already
   * has the same per-hull identity.
   */
  async createSeriesEntry(input: CreateSeriesEntryInput): Promise<string> {
    const identity: PerHullIdentity = {
      helm: input.helm,
      boatClass: input.boatClass,
      sailNumber: input.sailNumber,
    };
    await this.assertIdentityFreeInSeries(input.seriesId, identity);

    const entry: Partial<SeriesEntry> = {
      seriesId: input.seriesId,
      helm: input.helm,
      boatClass: input.boatClass,
      sailNumber: input.sailNumber,
      crew: input.crew,
      handicaps: input.handicaps,
      personalHandicapBand: input.personalHandicapBand,
      tags: input.tags,
    };
    return await this.seriesEntries.addEntry(entry);
  }

  /**
   * Writes the full proposed `SeriesEntry` with merge semantics. Identity-changing
   * updates are validated against all current entries in the series.
   */
  async updateSeriesEntryFromEdit(previous: SeriesEntry, next: SeriesEntry): Promise<void> {
    if (previous.id !== next.id) {
      throw new ScoreSmarterError(
        `RaceCompetitorMutator.updateSeriesEntryFromEdit: entry id mismatch ${previous.id} vs ${next.id}.`,
      );
    }
    if (previous.seriesId !== next.seriesId) {
      throw new ScoreSmarterError(
        `RaceCompetitorMutator.updateSeriesEntryFromEdit: cannot change seriesId for entry ${previous.id}.`,
      );
    }
    if (seriesEntriesEqual(previous, next)) return;

    const identityChanged =
      previous.helm !== next.helm ||
      previous.boatClass !== next.boatClass ||
      previous.sailNumber !== next.sailNumber;

    if (identityChanged) {
      const proposed: PerHullIdentity = {
        helm: next.helm,
        boatClass: next.boatClass,
        sailNumber: next.sailNumber,
      };
      const sameSeries = await this.seriesEntries.getSeriesEntries(previous.seriesId);
      const collision = findCollidingEntry(sameSeries, proposed, previous.id);
      if (collision) {
        throw new SeriesEntryIdentityConflictError(collision.id, previous.seriesId, proposed);
      }
    }

    const { id: _omitId, ...payload } = next;

    await this.runInBatch(batch => {
      batch.set(this.seriesEntries.seriesEntryDocRef(previous.id), payload as SeriesEntry, { merge: true });
    });

    const refs = await this.raceCompetitors.getCompetitorsForSeriesEntry(previous.id);
    const raceIds = [...new Set(refs.map(c => c.raceId))];
    for (const rid of raceIds) {
      await this.raceCalendar.ensureRaceDirty(rid);
    }
  }

  // --- Delete / repoint ------------------------------------------------------

  async deleteRaceCompetitor(competitor: RaceCompetitor): Promise<void> {
    const seriesEntryId = competitor.seriesEntryId;

    const others = (await this.raceCompetitors.getCompetitorsForSeriesEntry(seriesEntryId)).filter(
      c => c.id !== competitor.id,
    );

    await this.runInBatch(batch => {
      batch.delete(this.raceCompetitors.raceResultDocRef(competitor.id));
      if (others.length === 0) {
        batch.delete(this.seriesEntries.seriesEntryDocRef(seriesEntryId));
      }
    });

    await this.raceCalendar.ensureRaceDirty(competitor.raceId);
  }

  async repointRaceCompetitorToEntry(
    competitor: RaceCompetitor,
    nextSeriesEntryId: string,
    options?: { cleanupOldEntry?: 'ifOrphan' | 'never' },
  ): Promise<void> {
    const cleanup = options?.cleanupOldEntry ?? 'ifOrphan';
    const oldEntryId = competitor.seriesEntryId;

    const target = await this.seriesEntries.getSeriesEntry(nextSeriesEntryId);
    if (!target) {
      throw new ScoreSmarterError(
        `RaceCompetitorMutator: target series entry ${nextSeriesEntryId} not found.`,
      );
    }
    if (target.seriesId !== competitor.seriesId) {
      throw new ScoreSmarterError(
        `RaceCompetitorMutator: target series entry ${nextSeriesEntryId} is in series ` +
        `${target.seriesId}, expected ${competitor.seriesId}.`,
      );
    }

    const othersOnOld = (await this.raceCompetitors.getCompetitorsForSeriesEntry(oldEntryId)).filter(
      c => c.id !== competitor.id,
    );

    await this.runInBatch(batch => {
      batch.set(
        this.raceCompetitors.raceResultDocRef(competitor.id),
        { seriesEntryId: nextSeriesEntryId } as RaceCompetitor,
        { merge: true },
      );
      if (cleanup === 'ifOrphan' && othersOnOld.length === 0) {
        batch.delete(this.seriesEntries.seriesEntryDocRef(oldEntryId));
      }
    });

    await this.raceCalendar.ensureRaceDirty(competitor.raceId);
  }

  /** Deletes a series-entry doc if no race-results still reference it. */
  async cleanupOrphanedSeriesEntry(seriesEntryId: string, options?: { excludeCompetitorId?: string }): Promise<void> {
    const comps = await this.raceCompetitors.getCompetitorsForSeriesEntry(seriesEntryId);
    const remaining = options?.excludeCompetitorId
      ? comps.filter(c => c.id !== options.excludeCompetitorId)
      : comps;
    if (remaining.length > 0) return;

    await this.runInBatch(batch => {
      batch.delete(this.seriesEntries.seriesEntryDocRef(seriesEntryId));
    });
  }

  // --- Internal helpers ------------------------------------------------------

  private async assertIdentityFreeInSeries(seriesId: string, identity: PerHullIdentity): Promise<void> {
    const entries = await this.seriesEntries.getSeriesEntries(seriesId);
    const collision = findCollidingEntry(entries, identity);
    if (collision) {
      throw new SeriesEntryIdentityConflictError(collision.id, seriesId, identity);
    }
  }
}

/** Identifier helper retained for callers that need to mint ids outside the mutator. */
export function generateSeriesEntryId(boatClass: string, sailNumber: number): string {
  return generateSecureID(10000, `SE-${boatClass}-${sailNumber}`);
}

