import { inject, Injectable } from '@angular/core';
import { FirebaseApp } from '@angular/fire/app';
import { Firestore, doc, docData, getDoc, setDoc, updateDoc } from '@angular/fire/firestore';
import { connectFunctionsEmulator, getFunctions, httpsCallable } from 'firebase/functions';
import { RaceCalendarStore } from 'app/race-calender';
import { RaceCompetitorStore } from '../../services/race-competitor-store';
import { SeriesEntryStore } from '../../services/series-entry-store';
import { environment } from '../../../../environments/environment';
import { map, Observable } from 'rxjs';
import { CaptureSessionUploadService } from 'app/results-sheet-phone-capture/capture-session-upload.service';
import { ScanResponse, ScanRunRequest, ScanRunState, ScannedResultRow } from './scan-model';

const PARSE_RESULTS_SHEET_CALLABLE_TIMEOUT_MS = 318_000;
const UPLOAD_RESULTS_SHEET_IMAGE_CALLABLE_TIMEOUT_MS = 120_000;

@Injectable({ providedIn: 'root' })
export class ScannerOrchestrationService {
  private readonly app = inject(FirebaseApp);
  private readonly firestore = inject(Firestore);
  private readonly raceCalendarStore = inject(RaceCalendarStore);
  private readonly competitorStore = inject(RaceCompetitorStore);
  private readonly entryStore = inject(SeriesEntryStore);
  private readonly captureSessionUpload = inject(CaptureSessionUploadService);

  private readonly scanActivityMessages = [
    'Loading scan...',
    'Reading results sheet...',
    'Analysing handwriting...',
    'Checking race entries...',
    'Validating extracted rows...',
    'Analysing handwriting...',
    'Checking race entries...',
  ];

  defaultStageMessage(): string {
    return this.scanActivityMessages[0];
  }

  isMockMode(rawFlag: string | null | undefined): boolean {
    return rawFlag === '1';
  }

  async createCaptureSession(clubId: string, raceId: string): Promise<{
    sessionId: string;
    token: string;
    clubId: string;
    raceId: string;
    expiresAt: string;
  }> {
    const functions = getFunctions(this.app, 'europe-west1');
    if (environment.useEmulators) {
      try { connectFunctionsEmulator(functions, 'localhost', 5001); } catch { /* already configured */ }
    }
    const createFn = httpsCallable(functions, 'createResultsSheetCaptureSession', { timeout: 60_000 });
    const res = await createFn({ clubId, raceId });
    return res.data as {
      sessionId: string;
      token: string;
      clubId: string;
      raceId: string;
      expiresAt: string;
    };
  }

  async uploadFromCaptureSession(payload: {
    clubId: string;
    sessionId: string;
    token: string;
    imageBase64: string;
    imageMimeType: string;
  }): Promise<{ status: string; storagePath?: string }> {
    return this.captureSessionUpload.uploadFromCaptureSession(payload);
  }

  watchCaptureSession(clubId: string, sessionId: string): Observable<{
    status?: string;
    storagePath?: string;
    uploadedAt?: Date;
    expiresAt?: Date;
    scanResponse?: ScanResponse;
  } | null> {
    const ref = doc(this.firestore, `clubs/${clubId}/results-sheet-capture-sessions/${sessionId}`);
    return docData(ref).pipe(
      map(v => (v ?? null) as {
        status?: string;
        storagePath?: string;
        uploadedAt?: Date;
        expiresAt?: Date;
        scanResponse?: ScanResponse;
      } | null),
    );
  }

  async saveScanResponse(clubId: string, raceId: string, response: ScanResponse): Promise<void> {
    const ref = doc(this.firestore, `clubs/${clubId}/scan-results/${raceId}`);
    await setDoc(ref, { scanResponse: response, updatedAt: new Date() }, { merge: true });
  }

  async getScanResponse(clubId: string, raceId: string): Promise<ScanResponse | null> {
    const ref = doc(this.firestore, `clubs/${clubId}/scan-results/${raceId}`);
    const snap = await getDoc(ref);
    if (!snap.exists()) return null;
    return snap.data()['scanResponse'] as ScanResponse || null;
  }

  async clearScanResponse(clubId: string, raceId: string): Promise<void> {
    const ref = doc(this.firestore, `clubs/${clubId}/scan-results/${raceId}`);
    await updateDoc(ref, { scanResponse: null });
  }

  runScan(request: ScanRunRequest): Observable<ScanRunState> {
    return new Observable<ScanRunState>((subscriber) => {
      let idx = 0;
      subscriber.next({ status: 'running', stageMessage: this.defaultStageMessage() });
      const stageInterval = setInterval(() => {
        idx = (idx + 1) % this.scanActivityMessages.length;
        subscriber.next({ status: 'running', stageMessage: this.scanActivityMessages[idx] });
      }, 5000);

      const finish = () => clearInterval(stageInterval);

      void (async () => {
        try {
          const result = request.mockMode
            ? this.buildMockResponse(request.raceId)
            : await this.runCallableScan(request);
          subscriber.next({ status: 'success', result: this.applyAutoAccept(result) });
          subscriber.complete();
        } catch (err: unknown) {
          subscriber.next({ status: 'error', error: this.formatParseSheetError(err) });
          subscriber.complete();
        } finally {
          finish();
        }
      })();

      return finish;
    });
  }

  buildMockResponse(raceId: string): ScanResponse {
    const race = this.raceCalendarStore.allRaces().find(r => r.id === raceId);
    if (!race) {
      return { scannedResults: [], unreadableRowsCount: 0 };
    }

    const comps = this.competitorStore.selectedCompetitors().filter(c => c.raceId === raceId);
    const entries = this.entryStore.selectedEntries();
    const start = race.actualStart ?? race.scheduledStart;

    const rows = comps
      .map((c, rowIndex): ScannedResultRow | undefined => {
        const e = entries.find(se => se.id === c.seriesEntryId);
        if (!e) return undefined;
        const finish = new Date(start.getTime() + rowIndex * 4 * 60 * 1000 + 37 * 1000);
        const hh = String(finish.getHours()).padStart(2, '0');
        const mm = String(finish.getMinutes()).padStart(2, '0');
        const ss = String(finish.getSeconds()).padStart(2, '0');
        return {
          rowIndex: rowIndex + 1,
          matchedCompetitorId: c.id,
          overallRowConfidence: rowIndex % 4 === 0 ? 'MANUAL_CHECK' : 'HIGH',
          sailNumber: { value: String(e.sailNumber), confidence: rowIndex % 5 === 0 ? 'MANUAL_CHECK' : 'HIGH' },
          boatClass: { value: e.boatClass, confidence: 'HIGH' },
          time: { value: `${hh}:${mm}:${ss}`, confidence: rowIndex % 4 === 0 ? 'MANUAL_CHECK' : 'HIGH' },
          laps: { value: 3, confidence: 'HIGH' },
          status: 'OK',
          accepted: false,
        };
      })
      .filter((r): r is ScannedResultRow => !!r);

    const unmatched1: ScannedResultRow = {
      rowIndex: rows.length + 1,
      overallRowConfidence: 'AMBIGUOUS',
      sailNumber: { value: '9999', confidence: 'AMBIGUOUS' },
      boatClass: { value: 'ILCA 7', confidence: 'MANUAL_CHECK' },
      time: { value: '15:23:11', confidence: 'MANUAL_CHECK' },
      laps: { value: 3, confidence: 'HIGH' },
      status: 'OK',
      accepted: false,
    };

    const unmatched2: ScannedResultRow = {
      rowIndex: rows.length + 2,
      overallRowConfidence: 'AMBIGUOUS',
      sailNumber: { value: '9999', confidence: 'AMBIGUOUS' },
      boatClass: { value: 'ILCA 7', confidence: 'HIGH' },
      time: { value: '15:23:11', confidence: 'HIGH' },
      laps: { value: 3, confidence: 'HIGH' },
      status: 'OK',
      accepted: false,
    };

    return {
      scannedResults: rows.length > 0 ? [...rows, unmatched1, unmatched2] : [unmatched1],
      unreadableRowsCount: 0,
      pageNotes: 'Mock scan mode: generated rows from current race competitors.',
    };
  }

  private applyAutoAccept(response: ScanResponse): ScanResponse {
    const scannedResults = response.scannedResults.map(row => ({
      ...row,
      accepted: row.overallRowConfidence === 'HIGH' &&
        row.sailNumber?.confidence === 'HIGH' &&
        row.time?.confidence === 'HIGH',
    }));
    return { ...response, scannedResults };
  }

  private async runCallableScan(request: ScanRunRequest): Promise<ScanResponse> {
    const hasImage = !!request.imageBase64 && !!request.imageMimeType;
    const hasStoredPath = !!request.storagePath;
    if (!hasImage && !hasStoredPath) throw new Error('Missing image data for scan.');

    const functions = getFunctions(this.app, 'europe-west1');
    if (environment.useEmulators) {
      try { connectFunctionsEmulator(functions, 'localhost', 5001); } catch { /* already configured */ }
    }

    const uploadFn = httpsCallable(functions, 'uploadResultsSheetImage', {
      timeout: UPLOAD_RESULTS_SHEET_IMAGE_CALLABLE_TIMEOUT_MS,
    });
    const parseFn = httpsCallable(functions, 'parseStoredResultsSheet', {
      timeout: PARSE_RESULTS_SHEET_CALLABLE_TIMEOUT_MS,
    });

    let storedImagePath = request.storagePath ?? undefined;
    if (!storedImagePath) {
      const uploadRes = await uploadFn({
        imageBase64: request.imageBase64,
        imageMimeType: request.imageMimeType,
        clubId: request.clubId,
        raceId: request.raceId,
      });
      storedImagePath = (uploadRes.data as { storagePath?: string } | null)?.storagePath;
      if (!storedImagePath) throw new Error('Upload succeeded but no storagePath was returned.');
    }
    const res = await parseFn({
      scannerContext: request.scannerContext,
      clubId: request.clubId,
      raceId: request.raceId,
      storagePath: storedImagePath,
    });

    return res.data as ScanResponse;
  }

  private extractCallableDetails(err: unknown): Record<string, unknown> | undefined {
    if (!err || typeof err !== 'object') return undefined;
    const e = err as Record<string, unknown>;
    const d = e['details'];
    if (d && typeof d === 'object') return d as Record<string, unknown>;
    const customData = e['customData'];
    if (customData && typeof customData === 'object') {
      const inner = (customData as Record<string, unknown>)['details'];
      if (inner && typeof inner === 'object') return inner as Record<string, unknown>;
    }
    return undefined;
  }

  private formatParseSheetError(err: unknown): string {
    const message = err instanceof Error ? err.message : 'Error parsing image.';
    const details = this.extractCallableDetails(err);
    if (!details) return message;
    const lines = [message];
    const stage = details['stage'];
    const cause = details['cause'];
    if (typeof stage === 'string' && stage) lines.push(`Stage: ${stage}`);
    if (typeof cause === 'string' && cause) lines.push(`Cause: ${cause}`);
    return lines.join('\n');
  }
}

import { Injectable, inject } from '@angular/core';
import { Firestore, WriteBatch, getDoc, getDocs, writeBatch } from '@angular/fire/firestore';
import { RaceCalendarStore, Series } from 'app/race-calender';
import { Race } from 'app/race-calender/model/race';
import { RaceCompetitor, SeriesEntry, SeriesEntryStore } from 'app/results-input';
import { RaceCompetitorStore } from 'app/results-input/services/race-competitor-store';
import { scoreSeriesSnapshot } from 'app/scoring/core/public-api';
import { ScoringConfiguration } from 'app/scoring/model/scoring-configuration';
import { getHandicapValue } from 'app/scoring/model/handicap';
import { discardsForRaceIndex } from 'app/scoring/model/discard-profile';
import { isInFleet } from 'app/scoring/model/fleet-membership';
import { groupBy } from 'app/shared/utils/group-by';
import { PublishedRace } from '../model/published-race';
import { PublishedSeason, SeriesInfo } from '../model/published-season';
import { PublishedSeries } from '../model/published-series';
import { PUBLISHED_SEASONS_PATH, PUBLISHED_SERIES_PATH } from './published-results-store';
import { buildTagDefinitionSnapshot } from './published-tag-snapshot';
import { normalizeTagIds } from './resolved-tag';

import { ClubStore, FirestoreTenantService } from 'app/club-tenant';
import { competitorsForConfigRace, doesRaceRequireHandicap, isRaceScorable } from 'app/scoring/core/rules/eligibility';
import { startOfDay, subDays } from 'date-fns';
import { buildDncContext, DEFAULT_DNC_POLICY } from 'app/scoring/core/rules/dnc-context';

const SCORING_CANDIDATE_STATUSES = new Set<Race['status']>([
  'In progress',
  'Completed',
  'Published',
  'Verified',
]);

@Injectable({ providedIn: 'root' })
export class ScoringEngine {
  private firestore = inject(Firestore);
  private tenant = inject(FirestoreTenantService);
  private rcs = inject(RaceCompetitorStore);
  private seriesEntryStore = inject(SeriesEntryStore);
  private raceCalendarStore = inject(RaceCalendarStore);
  private clubStore = inject(ClubStore);

  /**
   * Publishes the results of a single race to the public results area.
   */
  async publishRace(race: Race): Promise<void> {
    await this.publishRaces([race]);
  }

  /**
   * Publishes multiple races at once, grouping them by series for efficiency and to avoid race conditions.
   */
  async publishRaces(races: Race[]): Promise<void> {
    if (races.length === 0) return;

    console.log(`ScoringEngine.publishRaces: Publishing ${races.length} races: ${races.map(r => r.id).join(', ')}`);

    const batch = writeBatch(this.firestore);
    const seasonUpdates = new Map<string, PublishedSeason>();
    const racesBySeries = groupBy(races, race => race.seriesId);

    for (const [seriesId, seriesRaces] of racesBySeries) {
      const raceIds = seriesRaces.map(r => r.id);
      await this.publishSeriesInternal(batch, seasonUpdates, seriesId, raceIds);
    }

    // Apply season updates to batch
    for (const [seasonId, seasonData] of seasonUpdates) {
      const seasonDoc = this.tenant.docRef<PublishedSeason>(PUBLISHED_SEASONS_PATH, seasonId);
      batch.set(seasonDoc, seasonData);
    }

    await batch.commit();
  }

  /**
   * Recalculates the complete series scores from scratch.
   */
  async scoreCompleteSeries(seriesId: string): Promise<void> {
    const batch = writeBatch(this.firestore);
    const seasonUpdates = new Map<string, PublishedSeason>();

    await this.publishSeriesInternal(batch, seasonUpdates, seriesId);

    // Apply season updates to batch
    for (const [seasonId, seasonData] of seasonUpdates) {
      const seasonDoc = this.tenant.docRef<PublishedSeason>(PUBLISHED_SEASONS_PATH, seasonId);
      batch.set(seasonDoc, seasonData);
    }

    // Clear the Series dirty flag
    const seriesDoc = this.tenant.docRef<Series>('series', seriesId);
    batch.update(seriesDoc, { dirty: false });

    await batch.commit();
  }

  /**
   * Internal method to publish a series. 
   * If additionalRaceIds is provided, it ensures those races are included even if not yet Published/Verified.
   */
  private async publishSeriesInternal(
    batch: WriteBatch,
    seasonUpdates: Map<string, PublishedSeason>,
    seriesId: string,
    additionalRaceIds: string[] = []
  ): Promise<void> {
    const series = await this.raceCalendarStore.getSeriesById(seriesId);
    if (!series) {
      console.error(`ScoringEngine: Series ${seriesId} not found in Firestore.`);
      throw new Error('Series not found');
    }

    // 1. Races to score are chosen by race status. Manual results entry sets status to
    //    In progress / Completed as competitors are recorded, so we do not also require
    //    "has competitor rows" or other heuristics here.
    const racesForSeries = await this.raceCalendarStore.getSeriesRacesById(seriesId);

    let candidateRaces = racesForSeries.filter(r => SCORING_CANDIDATE_STATUSES.has(r.status));

    // Ensure explicitly published race ids are included when they match the same status rules.
    for (const raceId of additionalRaceIds) {
      const race = racesForSeries.find(r => r.id === raceId);
      if (race && SCORING_CANDIDATE_STATUSES.has(race.status) && !candidateRaces.some(r => r.id === raceId)) {
        candidateRaces = [...candidateRaces, race];
      }
    }

    if (candidateRaces.length === 0) {
      console.log(`ScoringEngine: No races to publish for series ${seriesId}`);
    } else {
      // 2. Sort races chronologically
      candidateRaces.sort((a, b) => {
        const timeA = (a.actualStart || a.scheduledStart).getTime();
        const timeB = (b.actualStart || b.scheduledStart).getTime();
        return timeA - timeB;
      });

      // 3. Fetch all competitors and entries (needed for scoring and per-fleet filters).
      const allSeriesCompetitors = await this.rcs.getSeriesCompetitors(seriesId);
      const seriesEntries = await this.seriesEntryStore.getSeriesEntries(seriesId);

      console.log(`ScoringEngine: Series ${seriesId} - Races: ${candidateRaces.length}, Competitors: ${allSeriesCompetitors.length}, Entries: ${seriesEntries.length}`);

      const configsToScore = [series.primaryScoringConfiguration, ...(series.secondaryScoringConfigurations || [])];

      for (const config of configsToScore) {
        const isPrimary = config.id === series.primaryScoringConfiguration.id;
        const publishedSeriesId = isPrimary ? series.id : `${series.id}_${config.id}`;
        const publishedSeriesName = isPrimary ? series.name : `${series.name} - ${config.name}`;

        const scorableRaces = candidateRaces.filter(race =>
          isRaceScorable(race, config, allSeriesCompetitors, seriesEntries),
        );

        await this.rescoreAllRacesForConfig(batch, seasonUpdates, series, config, publishedSeriesId, publishedSeriesName, scorableRaces, allSeriesCompetitors, seriesEntries);
      }

      this.cleanupStaleSeries(batch, seasonUpdates, series, configsToScore);
    }

    // 4. Clear dirty for every race in the series. 
    for (const race of racesForSeries) {
      if (race.dirty) {
        const raceDoc = this.tenant.docRef<Race>('races', race.id);
        batch.update(raceDoc, { dirty: false });
      }
    }
  }

  private calculateDiscards(series: Series, raceCount: number): number {
    return discardsForRaceIndex(series, raceCount);
  }

  private async rescoreAllRacesForConfig(
    batch: WriteBatch,
    seasonUpdates: Map<string, PublishedSeason>,
    series: Series,
    config: ScoringConfiguration,
    publishedSeriesId: string,
    publishedSeriesName: string,
    racesToScore: Race[],
    allSeriesCompetitors: RaceCompetitor[],
    seriesEntries: SeriesEntry[]
  ): Promise<void> {
    if (racesToScore.length === 0) {
      this.savePublishedSeries(batch, publishedSeriesId, publishedSeriesName, config.fleet.id, [], []);
      const existingRaces = await this.readPublishedRaces(publishedSeriesId);
      this.savePublishedRaces(batch, publishedSeriesId, [], existingRaces);
      await this.prepareSeasonUpdate(
        seasonUpdates,
        series,
        publishedSeriesId,
        publishedSeriesName,
        config.fleet.id,
        0,
        0,
        undefined,
      );
      return;
    }

    const handicapScheme = config.handicapScheme;
    const anyRaceRequiresHandicap = racesToScore.some(race => doesRaceRequireHandicap(race.type));

    const filteredSeriesEntries = seriesEntries.filter(e =>
      isInFleet(e, config.fleet) &&
      (!anyRaceRequiresHandicap || getHandicapValue(e.handicaps, handicapScheme) != null)
    );

    let existingPublishedRaces: PublishedRace[] = [];
    let currentSeriesResults: PublishedSeries['competitors'] = [];

    const mergeStrategy = series.entryAlgorithm;
    const club = this.clubStore.club();
    const seriesDefaults = series.scoringAlgorithm === 'long'
      ? club?.longSeriesDefaults
      : club?.shortSeriesDefaults;
    const dncPolicy = seriesDefaults?.dncCalculation ?? DEFAULT_DNC_POLICY;
    const { dncPoints } = buildDncContext({
      racesToScore,
      config,
      seriesEntries: filteredSeriesEntries,
      allSeriesCompetitors,
      mergeStrategy,
      dncPolicy,
    });

    for (let i = 0; i < racesToScore.length; i++) {
      const race = racesToScore[i];

      const filteredCompetitors = competitorsForConfigRace(race, config, allSeriesCompetitors, seriesEntries);

      const raceIndex = i + 1;

      const { scoredRaces, seriesResults } = scoreSeriesSnapshot({
        raceToScore: race,
        competitorsInRace: filteredCompetitors,
        existingScoredRaces: existingPublishedRaces,
        seriesEntries: filteredSeriesEntries,
        config: {
          seriesType: series.scoringAlgorithm,
          discards: this.calculateDiscards(series, raceIndex),
          dncPoints,
          excludeNeverRaced: dncPolicy.excludeNeverRaced,
        },
        scoringConfiguration: config,
        mergeStrategy,
      });

      scoredRaces.forEach((r: PublishedRace) => {
        r.seriesId = publishedSeriesId;
        r.seriesName = publishedSeriesName;
      });

      existingPublishedRaces = scoredRaces;
      currentSeriesResults = seriesResults;
    }

    // Attach the immutable `tagDefinitions` snapshot to each PublishedRace
    // and the PublishedSeries doc, scoped to ids actually referenced by the
    // rows in each doc. Pulling colour/label metadata in at publish time
    // (vs. lookup at read time) keeps historical results stable when the
    // club later renames or deletes a tag definition.
    const clubTagDefinitions = club?.tagDefinitions ?? [];
    for (const race of existingPublishedRaces) {
      for (const result of race.results) {
        result.tags = normalizeTagIds(result.tags ?? [], clubTagDefinitions);
      }
      const ids = race.results.flatMap(r => r.tags);
      race.tagDefinitions = buildTagDefinitionSnapshot(ids, clubTagDefinitions);
    }
    for (const competitor of currentSeriesResults) {
      competitor.tags = normalizeTagIds(competitor.tags ?? [], clubTagDefinitions);
    }
    const seriesTagIds = currentSeriesResults.flatMap(c => c.tags);
    const seriesTagDefinitions = buildTagDefinitionSnapshot(seriesTagIds, clubTagDefinitions);

    this.savePublishedSeries(
      batch,
      publishedSeriesId,
      publishedSeriesName,
      config.fleet.id,
      currentSeriesResults,
      seriesTagDefinitions,
    );
    const existingRaces = await this.readPublishedRaces(publishedSeriesId);
    this.savePublishedRaces(batch, publishedSeriesId, existingPublishedRaces, existingRaces);
    await this.prepareSeasonUpdate(
      seasonUpdates,
      series,
      publishedSeriesId,
      publishedSeriesName,
      config.fleet.id,
      racesToScore.length,
      this.recentRaceCount(racesToScore, 6),
      this.latestScheduledStart(racesToScore),
    );
  }

  private async readPublishedRaces(publishedSeriesId: string): Promise<PublishedRace[]> {
    const racesCol = this.tenant.collectionRef<PublishedRace>(PUBLISHED_SERIES_PATH, publishedSeriesId, 'races');
    const snapshot = await getDocs(racesCol);
    return snapshot.docs.map(doc => {
      const race = doc.data();
      return {
        ...race,
        results: race.results.map(r => Array.isArray(r.tags) ? r : { ...r, tags: [] }),
        tagDefinitions: Array.isArray(race.tagDefinitions) ? race.tagDefinitions : [],
      };
    });
  }

  private savePublishedSeries(
    batch: WriteBatch,
    publishedSeriesId: string,
    publishedSeriesName: string,
    fleetId: string,
    results: PublishedSeries['competitors'],
    tagDefinitions: PublishedSeries['tagDefinitions'],
  ): void {
    const seriesDoc = this.tenant.docRef<PublishedSeries>(PUBLISHED_SERIES_PATH, publishedSeriesId);
    const publishedSeries: PublishedSeries = {
      id: publishedSeriesId,
      name: publishedSeriesName,
      fleetId: fleetId,
      competitors: results,
      tagDefinitions,
    };
    batch.set(seriesDoc, publishedSeries);
  }

  private savePublishedRaces(batch: WriteBatch, publishedSeriesId: string, scoredRaces: PublishedRace[], existingRaces: PublishedRace[]): void {
    // Save all scored races
    scoredRaces.forEach(race => {
      const raceDoc = this.tenant.docRef<PublishedRace>(PUBLISHED_SERIES_PATH, publishedSeriesId, 'races', race.id);
      batch.set(raceDoc, race);
    });

    // Delete orphans (simple diff)
    const scoredIds = new Set(scoredRaces.map(r => r.id));
    existingRaces.forEach(existing => {
      if (!scoredIds.has(existing.id)) {
        const raceDoc = this.tenant.docRef<PublishedRace>(PUBLISHED_SERIES_PATH, publishedSeriesId, 'races', existing.id);
        batch.delete(raceDoc);
      }
    });
  }

  private cleanupStaleSeries(
    batch: WriteBatch,
    seasonUpdates: Map<string, PublishedSeason>,
    series: Series,
    configsToScore: ScoringConfiguration[]
  ): void {
    const currentConfigIds = new Set(configsToScore.map(c => c.id === series.primaryScoringConfiguration.id ? series.id : `${series.id}_${c.id}`));
    for (const [, seasonData] of seasonUpdates) {
      const staleSeries = seasonData.series.filter(s => s.baseSeriesId === series.id && !currentConfigIds.has(s.id));
      for (const stale of staleSeries) {
        console.log(`ScoringEngine: Cleaning up stale series ${stale.id}`);
        // Remove from season index
        seasonData.series = seasonData.series.filter(s => s.id !== stale.id);
        // Delete published series document
        const seriesDoc = this.tenant.docRef(PUBLISHED_SERIES_PATH, stale.id);
        batch.delete(seriesDoc);
      }
    }
  }

  private async prepareSeasonUpdate(
    updates: Map<string, PublishedSeason>,
    series: Series,
    publishedSeriesId: string,
    publishedSeriesName: string,
    fleetId: string,
    raceCount: number,
    recentRaceCount6d: number,
    lastPublishedRaceStart: Date | undefined,
  ): Promise<void> {
    const seasonId = series.seasonId;
    let seasonData = updates.get(seasonId);

    if (!seasonData) {
      seasonData = (await this.readPublishedSeason(seasonId)) ?? undefined;
      if (!seasonData) {
        const seasonName = this.clubStore.club().seasons.find(s => s.id === seasonId)?.name || 'Unknown Season';
        seasonData = { id: seasonId, name: seasonName, series: [] };
      }
      updates.set(seasonId, seasonData);
    }

    const seriesInfo: SeriesInfo = {
      id: publishedSeriesId,
      baseSeriesId: series.id,
      name: publishedSeriesName,
      fleetId: fleetId,
      startDate: series.startDate || new Date(),
      endDate: series.endDate || new Date(),
      raceCount: raceCount,
      recentRaceCount6d,
    };
    if (lastPublishedRaceStart) {
      seriesInfo.lastPublishedRaceStart = lastPublishedRaceStart;
    }

    const existingIndex = seasonData.series.findIndex(s => s.id === publishedSeriesId);
    if (existingIndex === -1) {
      seasonData.series.push(seriesInfo);
    } else {
      seasonData.series[existingIndex] = seriesInfo;
    }
  }

  private async readPublishedSeason(seasonId: string): Promise<PublishedSeason | null> {
    const seasonDoc = this.tenant.docRef<PublishedSeason>(PUBLISHED_SEASONS_PATH, seasonId);
    const docSnap = await getDoc(seasonDoc);
    return docSnap.exists() ? docSnap.data() : null;
  }

  /** Counts races whose local race-date falls in the rolling N-day window (inclusive). */
  private recentRaceCount(races: Race[], days: number): number {
    const cutoffDay = startOfDay(subDays(new Date(), days)).getTime();
    return races.filter(r => startOfDay(r.actualStart ?? r.scheduledStart).getTime() >= cutoffDay).length;
  }

  /** Returns the latest scheduledStart across the supplied races, or undefined. */
  private latestScheduledStart(races: Race[]): Date | undefined {
    if (races.length === 0) return undefined;
    let latest = races[0].scheduledStart;
    for (const r of races) {
      if (r.scheduledStart > latest) {
        latest = r.scheduledStart;
      }
    }
    return latest;
  }
}

import { inject, Injectable } from '@angular/core';
import { Firestore, writeBatch } from '@angular/fire/firestore';
import { ClubStore } from 'app/club-tenant/services/club-store';
import { RaceCalendarStore } from 'app/race-calender/services/full-race-calander';
import { SeriesEntryStore } from './series-entry-store';
import {
  planSeriesEntryHandicapSync,
  type SeriesEntryHandicapSyncPlan,
} from './series-entry-handicap-sync';

const BATCH_WRITE_LIMIT = 450;

@Injectable({
  providedIn: 'root',
})
export class SeriesEntryHandicapSyncService {
  private readonly firestore = inject(Firestore);
  private readonly raceCalendar = inject(RaceCalendarStore);
  private readonly seriesEntries = inject(SeriesEntryStore);
  private readonly clubStore = inject(ClubStore);

  async plan(seriesId: string): Promise<SeriesEntryHandicapSyncPlan | null> {
    const series = await this.raceCalendar.getSeriesById(seriesId);
    if (!series) return null;

    const entries = await this.seriesEntries.getSeriesEntries(seriesId);
    const clubClasses = this.clubStore.club().classes;
    return planSeriesEntryHandicapSync(series, entries, clubClasses);
  }

  async apply(seriesId: string): Promise<SeriesEntryHandicapSyncPlan | null> {
    const syncPlan = await this.plan(seriesId);
    if (!syncPlan) return null;

    await this.writeHandicapUpdates(syncPlan);
    await this.markSeriesAndRacesDirty(seriesId);
    return syncPlan;
  }

  private async writeHandicapUpdates(syncPlan: SeriesEntryHandicapSyncPlan): Promise<void> {
    const { updated } = syncPlan;
    for (let i = 0; i < updated.length; i += BATCH_WRITE_LIMIT) {
      const chunk = updated.slice(i, i + BATCH_WRITE_LIMIT);
      const batch = writeBatch(this.firestore);
      for (const { entry, handicaps } of chunk) {
        batch.set(this.seriesEntries.seriesEntryDocRef(entry.id), { handicaps }, { merge: true });
      }
      await batch.commit();
    }
  }

  private async markSeriesAndRacesDirty(seriesId: string): Promise<void> {
    await this.raceCalendar.updateSeries(seriesId, { dirty: true });
    const races = await this.raceCalendar.getSeriesRacesById(seriesId);
    for (const race of races) {
      await this.raceCalendar.ensureRaceDirty(race.id);
    }
  }
}

