],
  templateUrl: 'entry-page.html',
  styles: [
    `
    @use "mixins" as mix;

    @include mix.centered-column-page(".content", 480px);

    app-races-panel {
      --races-panel-list-min-height: 200px;
      --races-panel-list-max-height: 420px;
