      width: 100%;
      display: flex;

      mat-button-toggle {
        flex: 1;
      }
    }

    .helm-crew-row {
      display: flex;
      gap: 12px;
      align-items: flex-start;
      margin: 5px 0;
    }

    .helm-crew-row mat-form-field {
      flex: 1;
      min-width: 0;
      margin-bottom: 0;
    }

    .handicap-line {
      display: flex;
      flex-wrap: wrap;
      align-items: baseline;
      gap: 6px 10px;
      margin-top: 10px;
      margin-bottom: 20px;
      font-size: 0.875rem;
      line-height: 1.35;
      color: var(--mat-sys-on-surface-variant);
    }
    .handicap-line-title {
      font-weight: 500;
      margin-right: 2px;
      color: var(--mat-sys-on-surface-variant);
    }
    .handicap-chip {
      color: var(--mat-sys-on-surface-variant);
      font-weight: 400;
    }
    .handicap-chip--empty {
      font-style: italic;
    }
    .boat-selection {
      display: flex;
      align-items: baseline;
      gap: 8px;
    }
    .search-field {
      flex-grow: 1;
      font-size: 16px;
