src/app/results-input/services/dirty-rac.defaultValue:
async (component, currentRoute, currentState, nextState) => {
  const raceStore = inject(RaceCalendarStore);
  const snackbar = inject(MatSnackBar);
  const dialog = inject(DialogsService);

  const scoringEngine = inject(ScoringEngine);

  // Find all races and series that have been marked as dirty
  const dirtyRaces = raceStore.allRaces().filter(race => race.dirty);

  if (dirtyRaces.length === 0) {
    return true; // No dirty data, allow navigation immediately.
  }

  console.log(`DirtyRaceGuard: Found ${dirtyRaces.length} race(s) to publish...`);

  snackbar.open('Scoring results', 'Cancel');

  try {
    for (const race of dirtyRaces) {
      await scoringEngine.publishRace(race);
    }
  } catch (e: unknown) {
    console.error(`DirtyRaceGuard:  Error encountered publishing race results
      ${dirtyRaces.map(race => race.id + '  ')}
      ${e}
      `);
    snackbar.dismiss();
    const ret = await dialog.confirm('Error processing results', 'Press OK to exit or cancel to remain on page');
    return ret;
  }
  snackbar.dismiss();

  return true; // Allow navigation to proceed.
}

src/app/results-input/services/dirty-ser.defaultValue:
async (component, currentRoute, currentState, nextState) => {
   const raceStore = inject(RaceCalendarStore);
   const snackbar = inject(MatSnackBar);
   const dialog = inject(DialogsService);

   const scoringEngine = inject(ScoringEngine);

   // Find all races and series that have been marked as dirty
   const dirtySeries = raceStore.allSeries().filter(series => series.dirty);

   if (dirtySeries.length === 0) {
      return true; // No dirty data, allow navigation immediately.
   }

   console.log(`DirtySeriesGuard: Found ${dirtySeries.length} series to publish...`);

   snackbar.open('Scoring results', 'Cancel');

   try {
      for (const series of dirtySeries) {
         await scoringEngine.scoreCompleteSeries(series.id);
      }

   } catch (e: unknown) {
      console.error(`DirtySeriesGuard:  Error encountered publishing series results
      ${dirtySeries.map(series => series.id + '  ')}
      ${e}
      `);
      snackbar.dismiss();
      const ret = await dialog.confirm('Error processing results', 'Press OK to exit or cancel to remain on page');
      return ret;
   }
   snackbar.dismiss();

   return true; // Allow navigation to proceed.
}

src/app/scoring/model/result-code-scorin.defaultValue:
(code: ResultCode): ResultCodeAlgorithm => {
  const short = getShortAlgorithm(code);

  // Rule A5.3 (Long Series): DNS/DNF/OCS points based on Starters + 1
  if (short === ResultCodeAlgorithm.compInSeries && isStartAreaComp(code)) {
    return ResultCodeAlgorithm.compInStartArea;
  }
  return short;
}

(code: ResultCode): ResultCodeAlgorithm => {
  if (code === 'OOD') return ResultCodeAlgorithm.clubOodAverage;
  if (code === 'RDGA') return ResultCodeAlgorithm.isafAvgAll;
  if (code === 'RDGB') return ResultCodeAlgorithm.isafAvgBefore;
  if ((['ZFP', 'SCP', 'XPA'] as ResultCode[]).includes(code)) return ResultCodeAlgorithm.scoringPenalty;
  if ((['DPI', 'RDG', 'RDGC'] as ResultCode[]).includes(code)) return ResultCodeAlgorithm.setByHand;
  if (code === 'OK') return ResultCodeAlgorithm.na;

  return ResultCodeAlgorithm.compInSeries;
}

